/* All views read one shared local state. No server or payment provider is contacted. */
'use strict';
(() => {
function activityReviews(a){const rows=[{user:'农场宠友',rating:5,content:'工作人员耐心讲解，和小动物的互动很治愈。'},...S.orders.filter(o=>o.activityId===a.id&&o.review).map(o=>o.review)];return `<div class="card pad"><h3>体验评价 <small class="muted">${rows.length}条 · 含1条初始示例</small></h3>${rows.map(r=>`<div class="comment"><div class="between"><strong>${E(r.user)}</strong><span class="accent">${'★'.repeat(r.rating)}</span></div><p class="muted">${E(r.content)}</p></div>`).join('')}</div>`;}
function boardingCare(o){if(o.type!=='boarding'||!['in_service','done'].includes(o.status))return '';return `<div class="spacer"></div><h3>寄养每日照护</h3><div class="spacer"></div>${B('boarding-scene','查看监护画面示意',o.id,'btn secondary full')}<p class="muted small" style="margin-top:10px">本地插画示意，无真实摄像头接入。24小时视频需另行连接设备。</p>${(o.care||[]).length?o.care.map(c=>`<div class="health-record"><h3>${E(c.date)} · ${E(c.kind)}</h3><p>${E(c.note)}</p></div>`).join(''):'<p class="muted small" style="margin-top:15px">暂无照护记录，可在下方演示工具中模拟记录。</p>'}`;}
function shell(content){const first=route.split('/')[0],group=['community','post','publish'].includes(first)?'community':['shop','product','cart','checkout'].includes(first)?'shop':['profile','pets','health','pet-edit','health-edit','member','points','coupons','addresses','favorites','settings'].includes(first)?'profile':'home';const nav=[['home','home','发现农场'],['community','chat','萌宠社区'],['shop','bag','宠物商城'],['profile','user','我的农场']];const unread=Farm.notifications().filter(m=>!m.read&&(S.settings.notify||!['health','activity'].includes(m.category))).length,cartCount=S.cart.reduce((n,c)=>n+c.qty,0);return `<aside class="sidebar">${A('home',`${img('logo','萌宠农场标志')}<div><strong>萌宠农场</strong><small>PAW FARM & FRIENDS</small></div>`,'brand')}<nav aria-label="主导航">${nav.map(([r,i,t])=>A(r,I(i)+`<span>${t}</span>`,'nav-link'+(r===group?' active':''))).join('')}</nav><div class="nav-label">MY COMPANIONS</div><nav aria-label="常用服务">${[['activities','calendar','活动预约'],['pets','paw','我的宠物'],['orders','ticket','我的订单'],['knowledge','book','养宠知识']].map(([r,i,t])=>A(r,I(i)+`<span>${t}</span>`,'nav-link'+(r===first?' active':''))).join('')}</nav><div class="side-bottom">${A('support',I('chat')+'<span>联系农场</span>','nav-link')}${A('settings',I('settings')+'<span>账号与设置</span>','nav-link')}<p class="side-note">把平凡的日子，过得毛茸茸。<br>© ${new Date().getFullYear()} PAW FARM</p></div></aside><div class="workspace"><header class="topbar"><div class="welcome">GOOD ${new Date().getHours()<12?'MORNING':'DAY'}<strong>欢迎来到萌宠农场 ${I('sun')}</strong></div>${A('home',img('logo','')+'萌宠农场','mobile-brand')}${`<form data-form="global-search" class="search">${I('search')}<input name="q" placeholder="搜索活动、好物、养宠知识" aria-label="全站搜索"><button aria-label="搜索">${I('arrow')}</button></form>`}<div class="top-actions">${A('search',I('search'),'icon-btn mobile-search')}${A('messages',I('bell')+(unread?`<span class="dot">${Math.min(99,unread)}</span>`:''),'icon-btn')}${A('cart',I('cart')+(cartCount?`<span class="dot">${cartCount}</span>`:''),'icon-btn')}${A('profile',img('dog','我的农场','avatar'))}<span class="user-name small">${E(S.user.name)}</span></div></header><main class="main" id="content">${Farm.error()?`<div class="note warm" role="alert" style="margin-bottom:20px">${E(Farm.error())} ${A('settings','管理数据 →','text-btn')}</div>`:''}${content}<footer class="footer"><span>在阳光里，把陪伴酿成日常。</span><span>PAW FARM · 本地演示 · 无真实付款</span></footer></main></div><nav class="mobile-nav" aria-label="底部导航">${nav.map(([r,i,t])=>A(r,I(i)+`<span>${{home:'发现',community:'社区',shop:'商城',profile:'我的'}[r]}</span>`,' '+(r===group?'active':''))).join('')}</nav>`;}
function content(){const [p,id,x]=route.split('/');switch(p){case'home':return home();case'activities':return activities();case'activity':return activity(id);case'booking':return booking(id);case'shop':return shop();case'product':return product(id);case'cart':return cart();case'checkout':return checkout(id||'cart');case'orders':return orders();case'order':return order(id);case'voucher':return voucher(id);case'result':return result(id);case'community':return community();case'post':return post(id);case'publish':return publish();case'knowledge':return knowledge();case'article':return article(id);case'profile':return profile();case'pets':return pets();case'pet-edit':return petEdit(id);case'health':return health(id);case'health-edit':return healthEdit(id,x);case'member':return member();case'points':return pointsPage();case'coupons':return coupons();case'addresses':return addresses();case'favorites':return favorites();case'messages':return messages();case'service':return service(id);case'adoption':return adoption();case'promo':return promo();case'support':return support();case'settings':return settings();case'search':return searchPage();default:return missing();}}
function capture(form){if(!form?.dataset.key)return {};const data=Object.fromEntries(new FormData(form));for(const el of form.querySelectorAll('input[type=checkbox][name]'))data[el.name]=el.checked;const d=draft(form.dataset.key);Object.assign(d,data);return {...d};}
function render(preserve=false){const y=preserve?window.scrollY:0;try{if(!Farm.error())Farm.expire();S=Farm.get();$('#app').innerHTML=shell(content());const qr=$('#voucher-qr');if(qr){const code=qrcode(0,'M');code.addData(qr.dataset.code);code.make();qr.innerHTML=code.createSvgTag({cellSize:4,margin:0,scalable:true});}document.title=(($('#content h1')?.textContent)||'萌宠农场')+' · 萌宠农场';window.scrollTo(0,y);clearInterval(heroTimer);if(route==='home'&&!matchMedia('(prefers-reduced-motion: reduce)').matches)heroTimer=setInterval(()=>{if(document.hidden||$('#modal').open)return;ui.hero=(ui.hero+1)%3;if($('#hero'))$('#hero').innerHTML=hero();},6500);}catch(e){$('#app').innerHTML=shell(head('页面暂时遇到问题')+empty('数据无法正常展示',e.message,A('settings','前往设置检查数据','btn')));console.error(e);}}
function go(next,replace=false){capture($('#content form[data-key]'));closeModal();next=next||'home';if(next.startsWith('booking/')&&route!==next)delete ui.drafts[next];current=route;route=next;depth=replace?depth:depth+1;history[replace?'replaceState':'pushState']({farm:true,depth},'','#'+route);render();}
function modal(title,body){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${E(title)}</h2>${B('close-modal',I('close'),'','icon-btn','aria-label="关闭对话框"')}</div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();m.scrollTop=0;}
function closeModal(){if($('#modal').open)$('#modal').close();}
function confirmAction(title,desc,fn){ui.confirm=fn;modal(title,`<p>${E(desc)}</p>${B('confirm','确认继续','','btn')}${B('close-modal','暂时不操作','','btn outline')}`);}
function payment(id){const o=get(Farm.get().orders,id);if(!o||o.status!=='pending')throw Error('订单当前无需支付');modal('演示收银台',`<div class="center"><div class="success-mark">${I('shield')}</div><h2>${M(o.total)}</h2><p style="margin:12px 0 24px">${E(o.name)}<br>本地模拟付款，不会扣款或唤起外部支付。</p></div>${B('pay-outcome',I('check')+' 模拟支付成功',id+'|success','btn')}${B('pay-outcome','模拟支付失败',id+'|failed','btn outline')}${B('pay-outcome','模拟取消支付',id+'|cancelled','btn outline')}`);}
function addressDialog(id){const a=id==='new'?{}:get(S.addresses,id);if(!a)throw Error('地址不存在');const key='address-form/'+id,d=draft(key,{id:a.id||'',name:a.name||S.user.name,phone:a.phone||S.user.phone,area:a.area||'',detail:a.detail||'',isDefault:a.isDefault||false});modal(a.id?'编辑收货地址':'新增收货地址',formStart('address',key)+hidden('id',d.id)+`<div class="form-grid">${contactFields(d)}${field('area','省市区',d.area,'text','required minlength="2" maxlength="80"')}${field('detail','街道、门牌号',d.detail,'text','required minlength="3" maxlength="150"')}<div class="field full">${check('isDefault','设为默认地址',d.isDefault)}</div></div>`+formEnd('保存地址'));}
async function copy(text){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);toast('已复制');return;}catch{}}modal('复制内容',`<p>可选中下方内容手动复制。</p><textarea class="input" rows="5" readonly>${E(text)}</textarea>`);$('#modal textarea').select();}
function healthFormUpload(d,key){const image=ui.uploads[key]?.[0];if(image)d.photo=image;return d;}
async function action(name,id,el){capture(el?.closest('form[data-key]')||$('#content form[data-key]'));const parts=id.split('|');switch(name){
 case'boarding-scene':modal('监护画面 · 本地示意',`<div class="monitor-scene">${img('dog','寄养房间宠物插画')}<span class="pill white">${new Date().toLocaleString('zh-CN')} · 演示画面</span></div><p style="margin-top:15px">这是本地插画示意，不是实时视频，也不会调用摄像头。真实24小时监控需要设备与视频服务。</p>`);return;
 case'memocard':{const o=get(S.orders,id);if(o.status!=='done'||o.type!=='activity')throw Error('完成体验后可领取纪念卡');const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="620" viewBox="0 0 900 620"><rect width="900" height="620" rx="28" fill="#e8efdf"/><circle cx="750" cy="90" r="100" fill="#e7cf8f"/><path d="M0 440Q200 300 420 440T900 400V620H0Z" fill="#a7bb91"/><text x="70" y="95" font-size="20" fill="#2c674e">PAW FARM · 萌宠农场</text><text x="70" y="210" font-size="45" fill="#253d35">把这份可爱，带回家。</text><text x="70" y="285" font-size="28" fill="#2c674e">${E(o.name)}</text><text x="70" y="345" font-size="22" fill="#6e846c">${E(o.contact.name)} · ${E(o.date)}</text><text x="70" y="560" font-size="17" fill="#253d35">本地演示纪念卡 · 不是现场摄影照片</text></svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='萌宠农场纪念卡.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('演示纪念卡已生成');return;}
 case'care-order':{const o=get(S.orders,id);modal('记录寄养每日照护（演示）',formStart('care','care/'+id)+hidden('id',id)+`<div class="form-grid">${field('date','照护日期',o.date,'date',`required min="${o.date}" max="${Farm.dateOf(new Date(new Date(o.endDate+'T12:00:00').getTime()-86400000))}"`)}${select('kind','照护类型','喂食',['喂食','遛弯','健康观察'])}${textarea('note','具体情况','','required minlength="3" maxlength="300"')}</div>`+formEnd('保存照护记录'));return;}
 case'checkout-boarding':confirmAction('模拟办理退房？','寄养订单将完成，可继续查看照护历史和评价。演示允许提前退房。',()=>{Farm.checkoutBoarding(id);render(true);});return;
 case'back':if(history.state?.farm&&history.state.depth>0)history.back();else go('home',true);return;
 case'close-modal':closeModal();return;
 case'confirm':{const cb=ui.confirm;ui.confirm=null;closeModal();if(cb)await cb();return;}
 case'hero':ui.hero=Number(id);if($('#hero'))$('#hero').innerHTML=hero();return;
 case'filter':ui.filters[parts[0]]=parts[1];render(true);return;
 case'favorite':Farm.favorite(parts[0],parts[1]);render(true);toast(fav(parts[0],parts[1])?'已加入收藏':'已取消收藏');return;
 case'share':{const url=new URL(location.href);url.hash='#'+(id||route);await copy(url.href);return;}
 case'booking-date':draft(route).date=id;draft(route).slot='';render(true);return;
 case'booking-slot':draft(route).slot=id;render(true);return;
 case'spec':ui.spec[parts[0]]=parts[1];render(true);return;
 case'add-cart':Farm.cartAdd(id,ui.spec[id]||'标准装');render(true);toast('已加入购物车');return;
 case'buy':{const key='checkout/buy';ui.drafts[key]={buyNow:true,productId:id,spec:ui.spec[id]||'标准装',qty:1,delivery:'express',addressId:S.addresses.find(a=>a.isDefault)?.id||'',name:S.user.name,phone:S.user.phone,couponId:'',usePoints:false,note:''};go(key);return;}
 case'checkout':delete ui.drafts['checkout/cart'];go('checkout/cart');return;
 case'cart-edit':ui.cartEdit=!ui.cartEdit;render(true);return;
 case'cart-toggle':Farm.cartToggle(id);render(true);return;
 case'cart-all':Farm.cartAll();render(true);return;
 case'cart-qty':if(Number(parts[1])===0){confirmAction('移出购物车？','这件商品的数量将归零。',()=>{Farm.cartChange(parts[0],0);render(true);});}else{Farm.cartChange(parts[0],Number(parts[1]));render(true);}return;
 case'delete-cart':confirmAction('移出购物车？','移除这件商品。',()=>{Farm.cartChange(id,0);render(true);});return;
 case'delete-selected':confirmAction('删除选中商品？','未选中的商品会保留。',()=>{Farm.cartDeleteSelected();render(true);});return;
 case'pay-order':payment(id);return;
 case'pay-outcome':Farm.pay(parts[0],parts[1]);closeModal();go('result/'+parts[0]);return;
 case'cancel-order':confirmAction('取消待支付订单？','预占名额 / 库存、优惠券与抵扣积分将返还。',()=>{Farm.cancel(id);render(true);toast('订单已取消，资源已释放');});return;
 case'refund-order':confirmAction('确认申请退款 / 退货？','发货前按规则模拟退款；发货后先申请退货。退款同步扣回消费奖励，返还库存、券与抵扣积分。',()=>{Farm.refund(id);render(true);toast('已更新售后状态');});return;
 case'finish-return':confirmAction('模拟确认退货？','确认演示商品已退回并完成模拟退款。',()=>{Farm.refund(id);render(true);toast('模拟退货退款完成');});return;
 case'ship':Farm.ship(id);render(true);toast('已模拟发货 / 备货');return;
 case'receive':confirmAction('确认收到商品？','确认后订单完成，可发表评价。',()=>{Farm.receive(id);render(true);});return;
 case'verify-order':{const o=get(S.orders,id);modal('模拟门店核销',`<p>粘贴订单券码或二维码内容。此操作仅演练门店流程，核销成功后不可重复使用。</p>${formStart('verify','verify')}<label class="field"><span>核销码</span><textarea name="code" required>${E(o.token)}</textarea></label>${formEnd('验证并核销')}`);return;}
 case'copy-code':await copy('PAWFARM:'+id+':'+get(S.orders,id).token);return;
 case'again':go(Farm.again(id));return;
 case'review':modal('分享这次体验',formStart('review','review/'+id)+hidden('id',id)+select('rating','评价星级',5,[[5,'★★★★★ 非常满意'],[4,'★★★★ 满意'],[3,'★★★ 一般'],[2,'★★ 不满意'],[1,'★ 很不满意']])+`<div class="spacer"></div>`+textarea('content','评价内容','','required minlength="3" maxlength="500"')+formEnd('发布评价'));return;
 case'reschedule':{const o=get(S.orders,id);modal('活动预约改期',formStart('reschedule','reschedule/'+id)+hidden('id',id)+`<div class="form-grid">${field('date','新日期',o.date,'date',`required min="${Farm.day()}" max="${Farm.day(6)}"`)}${select('slot','新时段',o.slot,Farm.slots(get(S.activities,o.activityId)).map(t=>[t.start,t.start+'—'+t.end]))}</div><p style="margin-top:15px">活动开始前24小时可办理，保存时重新核验余位。人数和金额不变。</p>`+formEnd('确认改期'));return;}
 case'like-post':Farm.likePost(id);render(true);return;
 case'follow':Farm.follow(id);render(true);return;
 case'like-article':Farm.likeArticle(id);render(true);return;
 case'topic':ui.drafts.publish={content:'',tag:'晒宠',topic:id};go('publish');return;
 case'view-image':modal('查看图片',`<img src="${E(safeImg(id))}" alt="查看大图" style="width:100%;max-height:65vh;object-fit:contain">`);return;
 case'remove-image':ui.uploads[parts[0]]?.splice(Number(parts[1]),1);render(true);return;
 case'weight':{const p=get(S.pets,id);modal('记录'+p.name+'的体重',formStart('weight','weight/'+id)+hidden('petId',id)+`<div class="form-grid">${field('date','记录日期',Farm.day(),'date',`required min="${p.birthday}" max="${Farm.day()}"`)}${field('value','体重（kg）',p.weight,'number','required min="0.01" max="150" step="0.01"')}</div>`+formEnd('保存体重'));return;}
 case'sign':Farm.sign();render(true);toast('签到成功 +5积分');return;
 case'redeem':confirmAction('兑换满49减10券？','使用500积分兑换一张全场券，30天有效。',()=>{Farm.redeem();render(true);toast('兑换成功，请在优惠券中查看');});return;
 case'claim':Farm.claim(id);render(true);toast('权益领取成功');return;
 case'address-edit':addressDialog(id);return;
 case'default-address':Farm.defaultAddress(id);render(true);return;
 case'delete-address':confirmAction('删除地址？','既有订单的地址快照不受影响。',()=>{Farm.deleteAddress(id);delete ui.drafts['address-form/'+id];render(true);});return;
 case'read-all':Farm.readAll();render(true);return;
 case'message':{const m=Farm.notifications().find(m=>m.id===id);Farm.readMessage(id);if(m)go(m.route);return;}
 case'profile-orders':ui.filters.orders=id;go('orders');return;
 case'apply-adopt':{const p=get(S.adoptable,id);modal('申请领养 · '+p.name,formStart('adopt','adopt/'+id)+hidden('petId',id)+`<div class="form-grid">${contactFields({name:S.user.name,phone:S.user.phone})}${field('home','居住情况（是否获同住人同意）','','text','required minlength="3" maxlength="100"')}${field('experience','养宠经验','','text','required minlength="3" maxlength="300"')}${textarea('reason','领养原因与照护计划','','required minlength="10" maxlength="500"')}</div>`+formEnd('提交领养申请'));return;}
 case'adopt-action':confirmAction('确认更新领养进度？','此操作为本地领养流程演练。',()=>{Farm.adoptionAction(parts[0],parts[1]);render(true);});return;
 case'adopt-followup':modal('记录领养回访',formStart('adopt-followup','followup/'+id)+hidden('id',id)+textarea('note','回访情况','','required minlength="5" maxlength="500"')+formEnd('保存回访'));return;
 case'invite-friend':modal('模拟好友通过邀请注册',`<p>此处模拟好友注册事件，校验手机号与唯一性后发放一次奖励。</p>`+formStart('invite','invite')+`<div class="form-grid">${contactFields({name:'',phone:''})}</div>`+formEnd('完成模拟注册'));return;
 case'friend-order':confirmAction('模拟好友完成首单？','向当前账户发放一次100积分和5元演示佣金。',()=>{Farm.friendOrder(id);render(true);toast('首单奖励已到账');});return;
 case'campaign':{if(!S.friends.length){toast('请先模拟邀请好友注册');return;}const c=S.campaigns[id],joined=id==='group'?c.members:c.helpers;const options=S.friends.filter(f=>!joined.includes(f.id)).map(f=>[f.id,f.name+' · '+f.phone]);if(!options.length){toast('需要再邀请一位不同好友');return;}modal(id==='group'?'模拟好友参团':'模拟好友助力',formStart('campaign','campaign/'+id)+hidden('kind',id)+select('friendId','选择不同的模拟好友',options[0][0],options)+formEnd('确认模拟参与'));return;}
 case'campaign-claim':Farm.campaignClaim(id);render(true);toast('奖励券已到账');return;
 case'withdraw':confirmAction('模拟结算佣金？','仅生成本地结算记录，不发生真实转账。',()=>{Farm.withdraw();render(true);});return;
 case'export':{const blob=new Blob([Farm.export()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='萌宠农场备份-'+Farm.day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出，请妥善保管');return;}
 case'demo-level':Farm.demoLevel(Number(id));delete ui.drafts.settings;render(true);toast('已切换演示等级 L'+id);return;
 case'reset':confirmAction('重置全部演示数据？','当前浏览器内的新增订单、宠物、图片等操作都会清除。建议先导出备份。',()=>{Farm.reset();ui.drafts={};ui.uploads={};ui.filters={};go('home');toast('已恢复初始演示数据');});return;
 default:throw Error('暂时无法识别该操作');
}}
async function submit(form){const type=form.dataset.form,d=capture(form),raw=Object.fromEntries(new FormData(form));Object.assign(d,raw);const key=form.dataset.key;switch(type){
 case'care':Farm.care(d.id,d);closeModal();render(true);toast('照护记录已同步');return;
 case'global-search':ui.filters.globalq=raw.q.trim();go('search');return;
 case'filter-search':ui.filters[key]=raw.q.trim();if(key==='globalq'&&route!=='search')go('search');else render(true);return;
 case'booking':{const id=Farm.createActivity(d);delete ui.drafts[key];go('order/'+id);payment(id);return;}
 case'checkout':{const id=Farm.createShop(d);delete ui.drafts[key];go('order/'+id);payment(id);return;}
 case'service':{const id=Farm.createService(d);delete ui.drafts[key];go('order/'+id);payment(id);return;}
 case'verify':{const id=Farm.verify(d.code.trim());closeModal();go('order/'+id);toast('核销成功，券码已失效');return;}
 case'review':Farm.review(d.id,Number(d.rating),d.content);closeModal();render(true);toast('评价已发布');return;
 case'reschedule':Farm.reschedule(d.id,d);closeModal();render(true);toast('已按新日期重新占位');return;
 case'publish':{const id=Farm.publish({...d,images:ui.uploads.publish||[]});delete ui.drafts[key];delete ui.uploads.publish;go('post/'+id);toast('发布成功 +10积分');return;}
 case'comment':Farm.comment(d.id,d.content);delete ui.drafts[key];render(true);toast('评论已保存');return;
 case'pet':{const id=Farm.savePet({...d,avatar:ui.uploads[key]?.[0]||''});delete ui.drafts[key];delete ui.uploads[key];go('health/'+id);toast('宠物档案已保存');return;}
 case'health':{Farm.saveHealth(healthFormUpload(d,key));delete ui.drafts[key];delete ui.uploads[key];go('health/'+d.petId);toast('健康记录已保存，提醒已同步');return;}
 case'weight':Farm.weight(d.petId,d.date,d.value);closeModal();render(true);toast('体重已记录');return;
 case'profile':Farm.updateProfile(d);delete ui.drafts[key];render(true);toast('资料已保存');return;
 case'address':{const id=Farm.saveAddress(d);delete ui.drafts[key];for(const k of Object.keys(ui.drafts))if(k.startsWith('checkout/'))ui.drafts[k].addressId=id;closeModal();render(true);toast('地址已保存');return;}
 case'adopt':Farm.applyAdopt(d);delete ui.drafts[key];closeModal();render(true);toast('领养申请已保存');return;
 case'adopt-followup':Farm.adoptionAction(d.id,'followup',d.note);closeModal();render(true);toast('回访已记录');return;
 case'invite':Farm.invite(d);delete ui.drafts[key];closeModal();render(true);toast('模拟注册成功 +50积分');return;
 case'campaign':Farm.campaign(d.kind,d.friendId);closeModal();render(true);toast('模拟参与成功');return;
 case'support':Farm.support(d.content);delete ui.drafts[key];render(true);$('.chat-log')?.scrollTo(0,99999);return;
 default:throw Error('表单类型无效');
}}
async function compress(file){if(!/^image\/(png|jpeg|webp)$/.test(file.type))throw Error('请选择JPG、PNG或WebP图片');if(file.size>8*1024*1024)throw Error('单张图片不能超过8MB');const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('图片无法读取'));image.src=url;});const scale=Math.min(1,1000/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let out=canvas.toDataURL('image/jpeg',.75);if(out.length>450000)out=canvas.toDataURL('image/jpeg',.4);if(out.length>600000)throw Error('图片压缩后仍过大，请使用较简单的照片');return out;}finally{URL.revokeObjectURL(url);}}
function boot(){route=decodeURIComponent(location.hash.slice(1))||'home';depth=history.state?.farm?history.state.depth:0;history.replaceState({farm:true,depth},'','#'+route);render();
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]'),link=e.target.closest('[data-route]');if(a){e.preventDefault();try{await action(a.dataset.action,a.dataset.id||'',a);}catch(err){error(err,a.closest('form'));}return;}if(link){e.preventDefault();go(link.dataset.route);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role=link],[role=button]')){e.preventDefault();e.target.click();}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(form.dataset.busy)return;form.dataset.busy='1';const btn=form.querySelector('[type=submit]');if(btn)btn.disabled=true;try{await submit(form);}catch(err){error(err,form);}finally{delete form.dataset.busy;if(btn)btn.disabled=false;}});
document.addEventListener('input',e=>{const form=e.target.closest('form[data-key]');if(form)capture(form);});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.dataset.upload){const key=el.dataset.upload,files=[...el.files];capture(el.closest('form'));const limit=key==='publish'?3:1;if(files.length+(ui.uploads[key]?.length||0)>limit)throw Error('最多可选择'+limit+'张图片');const results=[];for(const f of files)results.push(await compress(f));ui.uploads[key]=[...(ui.uploads[key]||[]),...results];render(true);toast('图片已压缩，保存表单后生效');}else if(el.id==='import-file'){const file=el.files[0];if(!file)return;if(file.size>12*1024*1024)throw Error('备份不能超过12MB');const text=await file.text();confirmAction('导入并替换本地数据？','将覆盖当前浏览器内全部演示数据，请确认已导出需要保留的记录。',()=>{Farm.import(text);ui.drafts={};ui.uploads={};go('home');toast('备份导入成功');});}else if(el.dataset.filter){ui.filters[el.dataset.filter]=el.value;render(true);}else if(el.hasAttribute('data-reprice')){capture(el.closest('form'));render(true);}}catch(err){error(err,e.target.closest('form'));}});
window.addEventListener('popstate',()=>{closeModal();route=decodeURIComponent(location.hash.slice(1))||'home';depth=history.state?.depth||0;render();});
window.addEventListener('hashchange',()=>{const next=decodeURIComponent(location.hash.slice(1))||'home';if(next!==route){route=next;depth=0;history.replaceState({farm:true,depth},'','#'+route);render();}});
window.addEventListener('farm:external',()=>{capture($('#content form[data-key]'));render(true);toast('已同步其他窗口的最新数据');});
setInterval(()=>{if(Farm.error())return;const rev=Farm.get().revision;try{Farm.expire();if(Farm.get().revision!==rev){render(true);toast('待支付订单已超时，预占资源已释放');}}catch(e){toast(e.message);}},30000);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
}
function member(){const l=Farm.level(S),used=S.orders.filter(o=>o.freeCheck&&o.quarter===Farm.quarter()&&!['cancelled','refunded'].includes(o.status)).length,monthClaims=S.claims.filter(c=>c.startsWith('monthly:'+Farm.day().slice(0,7))).length;return head('让陪伴，成为一种身份。','成长值决定等级，消费积分倍数、活动折扣与服务权益同步生效。')+`<div class="two-col"><div class="member-card card pad"><span class="eyebrow">PAW CLUB · L${l.n}</span><h1 style="margin:14px 0">${E(l.name)}</h1><p>当前成长值 ${S.user.growth} · 活动 ${l.discount/10} 折 · 消费积分 ${l.mult} 倍</p><div class="progress"><i style="width:${l.n===4?100:S.user.growth/Farm.levels[l.n].min*100}%"></i></div><div class="small">${l.n===4?'已达最高等级，继续享受陪伴':'距离下一等级还需 '+(Farm.levels[l.n].min-S.user.growth)+' 成长值'}</div></div><div class="card pad"><h3>我的专属权益</h3><div class="mini-list"><div class="grow"><h3>每月满减券</h3><p>满49减10 · 本月已领${monthClaims}/${l.coupons}张</p></div>${B('claim','领取','monthly','btn secondary small',monthClaims>=l.coupons?'disabled':'')}</div><div class="mini-list"><div class="grow"><h3>生日积分礼包</h3><p>L2起生日当月领100积分，L4为200积分</p></div>${B('claim','领取','birthday','btn secondary small')}</div><div class="mini-list"><div class="grow"><h3>季度免费体检</h3><p>本季度已预订${used}/${l.checks}次</p></div>${A('service/checkup','去预约','btn secondary small')}</div></div></div>${section('每一次陪伴，都值得被看见')}<div class="table-wrap"><table><thead><tr><th>会员权益</th>${Farm.levels.map(x=>`<th>L${x.n}<br>${E(x.name)}</th>`).join('')}</tr></thead><tbody>${[['成长值',...Farm.levels.map(x=>x.min+'—'+(x.max===Infinity?'∞':x.max-1))],['消费积分',...Farm.levels.map(x=>x.mult+'倍')],['活动折扣',...Farm.levels.map(x=>x.discount/10+'折')],['每月券',...Farm.levels.map(x=>x.coupons+'张')],['生日礼包','—','100积分','100积分','200积分'],['季度免费体检',...Farm.levels.map(x=>x.checks+'次')],['专属客服','普通','普通','优先咨询','专属咨询'],['预约服务','普通','普通','普通','优先协助']].map(r=>`<tr>${r.map(c=>`<td>${E(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="note" style="margin-top:22px">消费实付（不含运费）每1元获得1成长值，积分按当前等级倍数向下取整；每周三会员日积分再翻倍，当前有效倍数 ${Farm.effectiveMultiplier()} 倍；退款同步扣回。L4优先预约体现为专属咨询协助，不超售或跳过容量校验。${A('support',' 联系'+(l.n>=3?'专属':'在线')+'客服 →','text-btn')}</div>`;}
function pointsPage(){return head('小小积分，大大心意。','100积分抵1元，结算最多抵扣优惠后商品 / 服务金额的20%。')+`<div class="banner"><div><span class="eyebrow">MY PAW POINTS</span><h1 style="margin:7px 0">${S.user.points} <small>积分</small></h1><p>可用折合 ${M(Math.max(0,S.user.points))}（每100分=1元）</p></div>${B('sign',S.rewards.includes('sign:'+Farm.day())?'今天已签到':'签到 +5积分','','btn',S.rewards.includes('sign:'+Farm.day())?'disabled':'')}</div><div class="grid two"><div class="card pad"><h3>积分换好礼</h3><div class="spacer"></div><div class="between"><div><span class="price">¥10</span><p class="muted small">满49可用 · 全场通用 · 30天有效</p></div>${B('redeem','500积分兑换','','btn secondary')}</div></div><div class="card pad"><h3>让成长有迹可循</h3><p class="muted small" style="margin-top:14px">每日签到 +5 · 新增宠物 +20 · 登记疫苗 +10<br>发布动态 +10 · 帖子首次获赞 +1<br>邀请注册 +50 · 好友首单 +100<br>消费实付每1元积1分，按会员倍数计算；每周三再翻倍。</p></div></div>${section('积分收支明细','每笔奖励、抵扣和退款都有记录')}<div class="card pad">${S.ledger.map(l=>`<div class="ledger"><div><span>${E(l.label)}</span><small>${fullTime(l.time)}</small></div><strong class="${l.amount>0?'green':'accent'}">${l.amount>0?'+':''}${l.amount}</strong></div>`).join('')}</div><p class="muted small" style="margin-top:18px">退款会扣回消费奖励。若奖励已使用，余额可能暂为负数，后续收入先抵补余额。</p>`;}
function coupons(){const f=ui.filters.coupons||'available',names={available:'可使用',reserved:'订单预占',used:'已使用',expired:'已过期'},list=S.coupons.filter(c=>Farm.couponState(c)===f);return head('留一点小惊喜，给下一次。','按优惠后的金额判断门槛，每单使用一张券。')+filters('coupons',Object.entries(names))+(list.length?`<div class="grid two coupons">${list.map(c=>{const state=Farm.couponState(c);return `<article class="coupon ${state!=='available'?'inactive':''}"><div class="coupon-value"><strong><small>¥</small>${Farm.money(c.amount)}</strong><small>满${Farm.money(c.min)}可用</small></div><div class="grow"><h3>${E(c.name)}</h3><p>${c.scope==='all'?'全场通用':c.scope==='shop'?'限商城商品':'限农场活动'}${c.weekday?' · 每周三可用':''}<br>${c.expires} 到期</p>${state==='available'?A(c.scope==='activity'?'activities':'shop','去使用 '+I('arrow'),'text-btn'):c.usedBy?A('order/'+c.usedBy,names[state]+' · 查看订单','text-btn'):pill(names[state])}</div></article>`;}).join('')}</div>`:empty('暂无'+names[f]+'的优惠券','签到积攒积分，或在会员中心领取权益。',A('member','查看会员权益','btn')));}
function addresses(){return head('把心意，送到对的地方。','地址修改不会改变已创建订单中的收货信息。',B('address-edit',I('plus')+' 新增地址','new','btn'))+(S.addresses.length?`<div class="grid two">${S.addresses.map(a=>`<div class="card pad"><div class="between"><h3>${E(a.name)} <small class="muted">${E(a.phone)}</small></h3>${a.isDefault?pill('默认地址'):''}</div><p class="muted" style="margin:15px 0 22px">${E(a.area)}<br>${E(a.detail)}</p><div class="between wrap">${a.isDefault?'<span></span>':B('default-address','设为默认',a.id,'text-btn')}<div class="row">${B('address-edit',I('edit')+' 编辑',a.id,'text-btn')}${B('delete-address',I('trash')+' 删除',a.id,'text-btn danger')}</div></div></div>`).join('')}</div>`:empty('还没有收货地址','新增地址后可用于快递订单。',B('address-edit','新增地址','new','btn')));}
function favorites(){const f=ui.filters.favorites||'product',items=S.favorites.filter(x=>x.type===f),list={product:S.products,activity:S.activities,article:S.articles}[f];return head('喜欢的，都留在这里。','商品、活动和知识文章随时再看。')+filters('favorites',[['product','宠物好物'],['activity','农场活动'],['article','知识文章']])+(items.length?`<div class="grid ${f==='product'?'four':f==='activity'?'three':'two'}">${items.map(x=>get(list,x.id)).filter(Boolean).map(f==='product'?productCard:f==='activity'?activityCard:articleCard).join('')}</div>`:empty('还没有收藏','遇到喜欢的，点亮收藏就能在这里找到。'));}
function messages(){const f=ui.filters.messages||'all',list=Farm.notifications().filter(m=>f==='all'||m.category===f);return head('每一件在意的事，都提醒你。','订单、互动与健康信息，统一放在这里。',B('read-all','全部标为已读','','btn outline'))+filters('messages',[['all','全部'],['order','订单'],['health','健康提醒'],['activity','活动提醒'],['community','互动'],['system','系统'],['service','服务']])+(list.length?`<div class="card">${list.map(m=>`<div class="message ${m.read?'':'unread'}" data-action="message" data-id="${E(m.id)}" tabindex="0" role="button">${I(m.category==='health'?'health':'bell')}<div class="grow"><div class="between"><h3>${E(m.title)} ${m.read?'':'<span class="accent">·</span>'}</h3><small class="muted">${dateTime(m.time)}</small></div><p>${E(m.body)}</p><span class="text-btn">查看详情 →</span></div></div>`).join('')}</div>`:empty('暂时没有新消息','你的每一次操作都会在这里留下相关动态。'));}
function service(type){if(!Farm.services[type])return missing();const key='service/'+type,d=draft(key,{type,petId:S.pets[0]?.id||'',date:Farm.day(1),endDate:Farm.day(2),roomId:'standard',serviceId:'wash',slot:'09:00',tech:'小林',name:S.user.name,phone:S.user.phone,couponId:'',usePoints:false,freeCheck:false});let subtotal=type==='boarding'?get(Farm.rooms,d.roomId).price*Math.min(30,Math.max(1,Farm.days(d.date,d.endDate)||1)):type==='grooming'?get(Farm.grooming,d.serviceId).price:12800;const off=offers(d,type,subtotal),q=Farm.quote({...d,type,subtotal,freeCheck:d.freeCheck&&Farm.level(S).checks>0});return head(type==='boarding'?'你暂时离开，它被好好照顾。':type==='grooming'?'洗去尘土，留下可爱。':'多一份了解，多一份安心。',Farm.services[type].name+' · 选择宠物、项目与日期，完成本地预约。')+`<div class="banner"><div><h2>${Farm.services[type].name}</h2><p>${type==='boarding'?'标准间80元 / 晚 · 豪华间128元 / 晚 · VIP套间198元 / 晚，按实际夜晚占房。':type==='grooming'?'基础洗护68元起，三位技师独立排班，避免重复预约。':'单次128元 · L3每季1次 / L4每季2次免费，创建预约时预占权益。'}</p></div>${I(type==='boarding'?'house':type==='grooming'?'scissors':'health')}</div>`+(!S.pets.length?empty('先认识你的毛孩子','服务预约需要关联宠物档案。',A('pet-edit/new','添加宠物','btn')):formStart('service',key)+hidden('type',type)+`<div class="two-col"><div class="card pad"><h3 style="margin-bottom:22px">安排一份细心照顾</h3><div class="form-grid">${petSelect(d)}${type==='boarding'?select('roomId','寄养房型',d.roomId,Farm.rooms.map(r=>[r.id,r.name+' · '+M(r.price)+'/晚 · '+r.capacity+'间']),'data-reprice'):type==='grooming'?select('serviceId','服务项目',d.serviceId,Farm.grooming.map(g=>[g.id,g.name+' · '+M(g.price)+' · '+g.duration+'分钟']),'data-reprice'):''}${field('date',type==='boarding'?'入住日期':'预约日期',d.date,'date',`required min="${Farm.day()}" data-reprice`)}${type==='boarding'?field('endDate','离店日期',d.endDate,'date',`required min="${Farm.day(1)}" data-reprice`):select('slot','预约时段',d.slot,['09:00','11:00','14:00','16:00'])}${type!=='boarding'?select('tech','服务人员',d.tech,['小林','小陈','阿乐']):''}${contactFields(d)}</div><div class="note" style="margin-top:25px">${type==='boarding'?'每天09:00起可入住，最短1晚，最长30晚。退房日不占房。':'同一技师同一时段只接待一只宠物，提交时校验排班。'} 服务开始前至少24小时可退款。</div></div><div class="card pad summary"><h3>费用明细</h3><div class="spacer"></div>${off}${pricing(q,type==='boarding'?'房费（'+Math.min(30,Math.max(1,Farm.days(d.date,d.endDate)||1))+'晚）':'服务项目原价')}<div class="error form-error" role="alert"></div><button class="btn full" type="submit">提交服务预约 ${I('arrow')}</button><p class="muted small" style="margin-top:12px">提交及支付为演示。付款后可查看预约券并模拟到店核销。</p></div></div></form>`);}
function adoption(){return head('以领养，遇见另一种家人。','认真承诺，温柔陪伴，让每个小生命都有归处。')+`<div class="banner"><div><h2>领养前，请想好一生的陪伴。</h2><p>申请 → 审核 → 领养确认 → 后续回访，全部可在本地演练。</p></div>${I('heart')}</div><div class="grid three">${S.adoptable.map(p=>{const a=S.adoptions.find(a=>a.petId===p.id&&a.status!=='rejected');return `<div class="card"><div class="card-image">${img(p.art,p.name)}${pill(a?'申请进行中':'等待一个家','white')}</div><div class="card-body"><h2>${E(p.name)}</h2><p>${E(p.breed)} · ${E(p.age)}</p><p>${E(p.desc)}</p>${B('apply-adopt',a?'查看下方申请进度':'了解并申请领养',p.id,'btn secondary full',a?'disabled':'')}</div></div>`;}).join('')}</div>${section('我的领养申请','商家审核操作已明确标注为演示')}<div class="stack">${S.adoptions.length?S.adoptions.map(a=>{const p=get(S.adoptable,a.petId),names={pending:'待审核',approved:'审核通过',rejected:'未通过',adopted:'已领养'};return `<div class="card pad"><div class="between"><h3>${E(p.name)}的领养申请</h3>${pill(names[a.status])}</div><dl class="kv"><dt>申请人</dt><dd>${E(a.contact.name)} · ${E(a.contact.phone)}</dd><dt>居住情况</dt><dd>${E(a.home)}</dd><dt>养宠经验</dt><dd>${E(a.experience)}</dd><dt>领养原因</dt><dd>${E(a.reason)}</dd></dl>${a.followups.map(f=>`<div class="note" style="margin-top:10px">回访 ${fullTime(f.time)}<p>${E(f.text)}</p></div>`).join('')}${a.status==='adopted'?B('adopt-followup','记录领养回访',a.id,'btn secondary'):a.status==='approved'?B('adopt-action','确认领养（演示）',a.id+'|complete','btn'):a.status==='pending'?`<details class="demo-tools"><summary>演示工具 · 模拟领养审核</summary><p>用于演练审核状态，不连接实际领养机构。</p><div class="row">${B('adopt-action','审核通过',a.id+'|approve','btn secondary small')}${B('adopt-action','审核不通过',a.id+'|reject','btn outline small')}</div></details>`:''}</div>`;}).join(''):empty('还没有领养申请','先了解它的性格与生活需要，再做一份认真承诺。')}</div>`;}
function promo(){const pending=S.campaigns.commissions.filter(c=>!c.withdrawn).reduce((n,c)=>n+c.amount,0);return head('快乐分享，陪伴加倍。','邀请有礼、拼团与助力，所有好友行为均为明确的本地模拟。')+`<div class="banner"><div><span class="eyebrow">BETTER TOGETHER</span><h2>把可爱，分享给朋友</h2><p>邀请标识 PAW-DEMO-ME · 注册 +50积分 · 模拟好友首单 +100积分与5元演示佣金</p></div>${B('invite-friend',I('plus')+' 模拟好友注册','','btn')}</div><div class="grid two">${['group','bargain'].map(kind=>{const c=S.campaigns[kind],n=(kind==='group'?c.members:c.helpers).length;return `<div class="card pad"><div class="between"><h2>${kind==='group'?'三人拼团':'好友助力砍价'}</h2>${I(kind==='group'?'user':'gift')}</div><p class="muted small" style="margin:12px 0">${kind==='group'?'邀请2位不同好友成团，领商城满99减20券':'邀请2位不同好友助力，领商城满79减15券'} · 券7天有效</p><div class="progress"><i style="width:${n/2*100}%"></i></div><div class="between"><span class="muted small">已${kind==='group'?'加入':'助力'} ${n}/2 人</span>${n<2?B('campaign','选择好友模拟'+(kind==='group'?'参团':'助力'),kind,'btn secondary small'):B('campaign-claim',c.claimed?'已领取':'领取奖励券',kind,'btn small',c.claimed?'disabled':'')}</div></div>`;}).join('')}</div>${section('邀请记录','同一手机号仅可注册、奖励一次')}<div class="card pad">${S.friends.length?S.friends.map(f=>`<div class="mini-list">${img('dog',f.name,'avatar')}<div class="grow"><h3>${E(f.name)}</h3><p>${E(f.phone)} · ${f.firstOrder?'已完成模拟首单':'已模拟注册'}</p></div>${B('friend-order',f.firstOrder?'首单奖励已发':'模拟好友首单',f.id,'btn secondary small',f.firstOrder?'disabled':'')}</div>`).join(''):empty('还没有邀请记录','点击“模拟好友注册”演练邀请奖励。')}</div>${section('我的演示佣金')}<div class="card pad"><div class="between"><div><span class="muted small">待模拟结算</span><div class="price">${M(pending)}</div></div>${B('withdraw','模拟提现结算','','btn',pending?'':'disabled')}</div><p class="muted small" style="margin-top:12px">演示佣金仅用于验证记录，不涉及真实分佣或转账。</p>${S.campaigns.withdrawals.map(w=>`<div class="ledger"><span>${fullTime(w.time)} · 已模拟结算</span><strong>${M(w.amount)}</strong></div>`).join('')}</div>`;}
function support(){const l=Farm.level(S);return head(l.n>=3?'专属陪伴，随时在这里。':'有什么想问的？','本地演示客服 · 支持预约、订单退款与健康记录问题。')+`<div class="reading card pad"><div class="note">${l.n>=3?'L'+l.n+'专属咨询'+(l.n===4?' · 预约优先协助':'')+'：请留下问题，由演示客服记录。':'欢迎咨询，输入“预约”“退款”或“疫苗”可查看对应办理方式。'}</div><div class="chat-log">${S.support.length?S.support.map(c=>`<div class="bubble ${c.user?'mine':''}">${E(c.text)}</div>`).join(''):'<div class="bubble">你好，这里是萌宠农场演示客服。有什么可以帮到你？</div>'}</div>${formStart('support','support')}${textarea('content','你的问题',draft('support').content||'','required minlength="3" maxlength="500" placeholder="想咨询什么呢？"')}${formEnd('发送消息')}</div>`;}
function settings(){const d=draft('settings',{name:S.user.name,phone:S.user.phone,birthday:S.user.birthday,notify:S.settings.notify});return head('属于你的农场设置。','个人资料和本地数据管理。')+`<div class="two-col"><div class="card pad"><h3>个人资料</h3><div class="spacer"></div>${formStart('profile','settings')}<div class="form-grid">${contactFields(d)}${field('birthday','出生日期（用于生日礼）',d.birthday,'date',`required max="${Farm.day()}"`)}<div class="field" style="justify-content:center">${check('notify','在页面显示健康与活动提醒',d.notify)}</div></div>${formEnd('保存资料')}</div><div class="stack"><div class="card pad"><h3>我的数据，我来保管</h3><p class="muted small" style="margin:14px 0 20px">数据存放在当前浏览器中。导出包含宠物、订单、图片和联系方式，导入将替换本地全部演示数据。</p><div class="row wrap">${B('export',I('download')+' 导出备份','','btn secondary')}<label class="btn outline">导入备份<input type="file" accept="application/json,.json" id="import-file" hidden></label></div><p class="muted small" style="margin-top:15px">使用同一个地址访问可保留数据。file与localhost、不同端口可能是不同的存储空间。</p></div><details class="demo-tools"><summary>演示工具 · 等级测试与数据重置</summary><p>切换等级会修改成长值，便于测试折扣与权益；积分余额不会随之增加。重置会清除当前全部演示操作。</p><div class="row wrap">${[1,2,3,4].map(n=>B('demo-level','L'+n,n,'btn outline small')).join('')}</div><div class="spacer"></div>${B('reset','重置演示数据','','btn danger small')}</details></div></div>`;}
function searchPage(){const q=ui.filters.globalq||'',products=S.products.filter(p=>p.name.includes(q)),activities=S.activities.filter(a=>a.name.includes(q)),articles=S.articles.filter(a=>a.title.includes(q));return head('发现一份喜欢。',q?'“'+q+'” 的搜索结果':'搜索活动、商品或养宠知识。')+searchForm('globalq','搜索你感兴趣的内容')+(q?`${section('农场活动')}<div class="grid three">${activities.map(activityCard).join('')||'<p class="muted">没有相关活动</p>'}</div>${section('宠物好物')}<div class="grid four">${products.map(productCard).join('')||'<p class="muted">没有相关商品</p>'}</div>${section('养宠知识')}<div class="grid two">${articles.map(articleCard).join('')||'<p class="muted">没有相关文章</p>'}</div>`:'');}
function missing(){return head('这条小路，暂时走不通。')+empty('没有找到这条记录','它可能已被删除，或链接已失效。',A('home','回到农场','btn'));}
function orderArt(o){return o.type==='activity'?get(S.activities,o.activityId)?.art||'farm':o.type==='shop'?get(S.products,o.items[0]?.productId)?.art||'food':o.type==='boarding'?'dog':o.type==='grooming'?'wash':'cat';}
function orderActions(o,detail=false){let out='';if(o.status==='pending')out+=B('cancel-order','取消订单',o.id,'btn outline small')+B('pay-order','继续支付',o.id,'btn small');if(Farm.cancelAllowed(o))out+=B('refund-order','申请退款',o.id,'btn outline small');if(o.status==='paid'&&o.type!=='shop')out+=A('voucher/'+o.id,I('qr')+' 预约券码','btn small');if(o.type==='activity'&&Farm.cancelAllowed(o))out+=B('reschedule','预约改期',o.id,'btn outline small');if(o.status==='shipped')out+=B('refund-order','申请退货',o.id,'btn outline small')+B('receive','确认'+(o.delivery==='pickup'?'提货':'收货'),o.id,'btn small');if(o.status==='done'&&o.type==='activity')out+=B('memocard','领取纪念卡（演示）',o.id,'btn secondary small');if(o.status==='done'&&!o.review)out+=B('review','评价订单',o.id,'btn small');if(['done','cancelled','refunded'].includes(o.status))out+=B('again',o.type==='shop'?'再次购买':'再次预约',o.id,'btn outline small');if(!detail)out+=A('order/'+o.id,'查看详情','btn outline small');return out;}
function orders(){const f=ui.filters.orders||'all',type=ui.filters.orderType||'all';let list=S.orders.filter(o=>(f==='all'||(f==='paid'?['paid','shipped','return_requested','in_service'].includes(o.status):f==='closed'?['cancelled','refunded'].includes(o.status):o.status===f))&&(type==='all'||o.type===type));return head('每一份快乐，都有记录。','预约、购物与服务订单，统一查看和办理。')+filters('orders',[['all','全部'],['pending','待支付'],['paid','待履约'],['done','已完成'],['closed','取消 / 退款']])+`<div style="margin-bottom:20px;max-width:220px">${select('orderType','订单类型',type,[['all','所有类型'],['activity','农场活动'],['shop','商城订单'],['boarding','宠物寄养'],['grooming','洗护美容'],['checkup','健康体检']],'data-filter="orderType"')}</div>`+(list.length?list.map(o=>`<article class="card order-card"><div class="between"><span class="order-id">${E(o.id)}</span>${pill(status(o),o.status==='pending'?'orange':'')}</div><div class="order-body">${img(orderArt(o),o.name)}<div class="grow">${A('order/'+o.id,`<h3>${E(o.name)}</h3>`)}<p class="muted small">${o.type==='shop'?'共'+o.items.reduce((n,i)=>n+i.qty,0)+'件 · '+(o.delivery==='express'?'快递配送':'到店自提'):E(o.date)+' '+E(o.slot||'')+(o.type==='activity'?' · '+o.people+'人':'')}<br>${dateTime(o.created)}</p></div><span class="price">${M(o.total)}</span></div><div class="actions">${orderActions(o)}</div></article>`).join(''):empty('这里暂时没有订单','选一份喜欢的体验，开始新的故事。',A('activities','去预约','btn')));}
function order(id){const o=get(S.orders,id);if(!o)return missing();const pet=get(S.pets,o.petId),lastPayments=S.payments.filter(p=>p.orderId===id);return head('订单详情','订单记录与所有状态均保存在当前浏览器。')+`<div class="status-banner"><span class="eyebrow">${o.type==='shop'?'PAW SHOP':'PAW EXPERIENCE'}</span><h2>${E(status(o))}</h2><p>${o.status==='pending'?'请在 '+fullTime(o.expires)+' 前完成演示支付，超时自动释放资源。':o.status==='paid'?'支付成功，期待这次温柔相遇。':o.status==='refunded'?'模拟退款已完成，优惠与占用资源已按规则返还。':o.status==='done'?'谢谢你的陪伴，欢迎下次再来。':'在这里查看订单的最新进展。'}</p></div><div class="two-col"><div class="stack"><div class="card pad"><div class="mini-list">${img(orderArt(o),o.name)}<div><h2>${E(o.name)}</h2><p>${E(o.type==='shop'?'农场精选好物':'到店服务预约')}</p></div></div><dl class="kv"><dt>订单编号</dt><dd>${E(o.id)}</dd><dt>创建时间</dt><dd>${fullTime(o.created)}</dd>${o.paidAt?`<dt>支付时间</dt><dd>${fullTime(o.paidAt)} · 本地模拟</dd>`:''}${o.type!=='shop'?`<dt>服务日期</dt><dd>${E(o.date)} ${E(o.slot)}${o.endDate?' 至 '+E(o.endDate)+'（'+o.nights+'晚）':''}</dd><dt>关联宠物</dt><dd>${E(pet?.name||'未携宠')}</dd>${o.type==='activity'?`<dt>入场人数</dt><dd>${o.adults}成人 · ${o.kids}儿童 · 共${o.people}人</dd>`:`<dt>服务安排</dt><dd>${E(o.tech||Farm.rooms.find(r=>r.id===o.roomId)?.name||'农场工作人员')}</dd>`}`:`<dt>配送方式</dt><dd>${o.delivery==='express'?'快递配送':'到店自提 · '+E(o.store)}</dd>${o.address?`<dt>收货地址</dt><dd>${E(o.address.area+' '+o.address.detail)}</dd>`:''}`}<dt>联系人</dt><dd>${E(o.contact.name)} · ${E(o.contact.phone)}</dd>${o.note?`<dt>订单备注</dt><dd>${E(o.note)}</dd>`:''}</dl>${o.items.map(i=>`<div class="mini-list"><div class="grow"><h3>${E(i.name)}</h3><p>${E(i.spec)} × ${i.qty}</p></div><strong>${M(i.price*i.qty)}</strong></div>`).join('')}</div>${o.tracking.length?`<div class="card pad"><h3>${o.delivery==='pickup'?'自提进度':'模拟物流'}</h3><p class="muted small">${E(o.trackingId||'')}</p><div class="timeline">${o.tracking.map(t=>`<div><strong>${E(t.text)}</strong><p class="muted">${fullTime(t.time)}</p></div>`).join('')}</div></div>`:''}${o.review?`<div class="card pad"><h3>我的评价 <span class="accent">${'★'.repeat(o.review.rating)}</span></h3><p class="pre muted" style="margin-top:12px">${E(o.review.content)}</p></div>`:''}${lastPayments.length?`<div class="card pad"><h3>演示支付记录</h3>${lastPayments.map(p=>`<div class="ledger"><span>${fullTime(p.time)}</span><strong class="small">${{success:'成功',failed:'失败',cancelled:'用户取消'}[p.outcome]} · ${M(p.amount)}</strong></div>`).join('')}</div>`:''}</div><div class="card pad summary"><h3>金额明细</h3>${pricing(o)}<div class="row wrap">${orderActions(o,true)}</div>${o.status==='paid'&&o.type!=='shop'?`<div class="note" style="margin-top:18px">到店凭专属二维码核销，请勿向无关人员分享券码。</div>`:''}${boardingCare(o)}${demoOrder(o)}</div></div>`;}
function demoOrder(o){let actions='';if(o.type==='shop'&&o.status==='paid')actions=B('ship',o.delivery==='pickup'?'模拟门店备货':'模拟商家发货',o.id,'btn outline small');if(o.type!=='shop'&&o.status==='paid')actions=B('verify-order','模拟到店核销',o.id,'btn outline small');if(o.type==='boarding'&&o.status==='in_service')actions=B('care-order','记录每日照护',o.id,'btn outline small')+' '+B('checkout-boarding','模拟退房',o.id,'btn outline small');if(o.status==='return_requested')actions=B('finish-return','模拟确认退货并退款',o.id,'btn outline small');return actions?`<details class="demo-tools"><summary>演示工具 · 商家 / 服务端操作</summary><p>用于完整演练流程，不代表真实商家操作。活动可模拟提前到店，核销后券码立即失效。</p>${actions}</details>`:'';}
function voucher(id){const o=get(S.orders,id);if(!o)return missing();if(o.type==='shop'||o.status!=='paid')return head('预约券码')+empty('当前券码不可使用',status(o),A('order/'+id,'查看订单','btn'));return head('带上这份快乐，出发吧。','专属券码与当前订单绑定，核销一次即失效。')+`<div class="reading card pad center"><span class="eyebrow">YOUR LITTLE HAPPY TICKET</span><h1 style="margin:16px 0 8px">${E(o.name)}</h1>${pill('待到店使用')}<div id="voucher-qr" class="qr-box" data-code="${E('PAWFARM:'+o.id+':'+o.token)}"></div><p>${E(o.date)} · ${E(o.slot)}${o.people?' · '+o.people+'人':''}</p><p class="muted small" style="margin:8px 0 20px">${E(o.contact.name)} · ${E(o.contact.phone)}</p><div class="code">${E(o.token)}</div><div class="row wrap" style="justify-content:center;margin-top:20px">${B('copy-code','复制核销码',o.id,'btn secondary')}${A('order/'+id,'查看订单','btn outline')}</div>${demoOrder(o)}</div>`;}
function result(id){const o=get(S.orders,id);if(!o)return missing();const ok=o.status!=='pending'&&!['cancelled','refunded'].includes(o.status);return head('支付结果')+`<div class="reading card pad center" style="padding:50px 24px"><div class="success-mark">${I(ok?'check':'clock')}</div><h1>${ok?'支付成功，快乐已就位。':'支付尚未完成'}</h1><p class="muted" style="margin:15px 0 22px">${ok?'本地模拟支付成功，没有实际扣款。':'失败或取消支付会保留待支付订单，超时自动释放资源。'}<br>${E(o.name)} · ${M(o.total)}</p><div class="row wrap" style="justify-content:center">${!ok?B('pay-order','重新演示支付',id,'btn'):o.type!=='shop'?A('voucher/'+id,'查看预约券码','btn'):''}${A('order/'+id,'查看订单','btn outline')}${A('home','回到首页','btn secondary')}</div></div>`;}
function author(p){return p.author==='me'?{id:'me',name:S.user.name,art:'dog'}:get(S.authors,p.author)||{id:'unknown',name:'农场宠友',art:'dog'};}
function postCard(p,detail=false){const a=author(p);return `<article class="card post"><div class="post-head">${img(a.art,a.name,'avatar')}<div class="grow"><strong>${E(a.name)}</strong><small>${dateTime(p.time)} · ${E(p.tag)}</small></div>${a.id!=='me'?B('follow',S.follows.includes(a.id)?'已关注':'+ 关注',a.id,'btn secondary small'):pill('我的帖子')}</div><span class="topic"># ${E(p.topic)}</span><div class="post-content">${detail?E(p.content):A('post/'+p.id,E(p.content))}</div>${p.images.length?`<div class="post-images ${p.images.length===1?'single':''}">${p.images.map((src,i)=>`<img src="${E(safeImg(src))}" alt="${E(a.name)}分享的图片${i+1}" loading="lazy" data-action="view-image" data-id="${E(src)}" tabindex="0">`).join('')}</div>`:''}<div class="post-footer">${B('like-post',I('heart')+' '+p.likes,p.id,p.liked?'liked':'')}${A('post/'+p.id,I('chat')+' '+(p.baseComments+p.comments.length))}${B('share',I('share')+' 分享','post/'+p.id)}</div></article>`;}
function community(){const f=ui.filters.community||'推荐',q=ui.filters.communityq||'';let list=S.posts.filter(p=>(f!=='关注'||S.follows.includes(p.author))&&(f!=='我的'||p.author==='me')&&((p.content+p.topic+author(p).name).includes(q)));if(f==='最新')list.sort((a,b)=>b.time-a.time);return head('可爱的日常，值得分享。','在这里，遇见和你一样爱它的人。',A('publish',I('plus')+' 发布动态','btn'))+`<div class="two-col"><div>${filters('community',['推荐','关注','最新','我的'].map(x=>[x,x]))}${list.length?list.map(p=>postCard(p)).join(''):empty('还没有相关动态','关注喜欢的宠友，或分享你的第一条动态。',A('publish','记录一份可爱','btn'))}</div><aside class="stack"><div class="card pad"><h3>发现同频宠友</h3><div class="spacer"></div>${searchForm('communityq','搜索动态、作者或话题')}</div><div class="card pad"><span class="eyebrow">TODAY’S TOPICS</span><h3 style="margin:10px 0 18px">今天，想聊些什么？</h3>${['农场的一天','养宠日常','科学喂养','萌宠成长记'].map((t,i)=>`<div class="mini-list"><span class="accent">0${i+1}</span><div class="grow"><strong class="small"># ${t}</strong></div>${B('topic',I('arrow'),t,'text-btn')}</div>`).join('')}</div><div class="note">分享真实体验，友好交流。图片会压缩后保存在本地，请勿上传敏感资料。</div></aside></div>`;}
function post(id){const p=get(S.posts,id);if(!p)return missing();return head('一份可爱的日常')+`<div class="reading">${postCard(p,true)}<div class="card pad"><h3>宠友评论 <small class="muted">${p.comments.length}条可见评论</small></h3><p class="muted small">原演示热度 ${p.baseComments} 条，仅作为历史计数；以下为实际保存的评论。</p>${p.comments.map(c=>`<div class="comment"><div class="between"><strong>${E(c.user)}</strong><small class="muted">${dateTime(c.time)}</small></div><p class="pre">${E(c.text)}</p></div>`).join('')}${formStart('comment','comment/'+id)}${hidden('id',id)}<div class="spacer"></div>${textarea('content','说点温柔的话',draft('comment/'+id).content||'','required maxlength="500" placeholder="分享你的想法…"')}${formEnd('发布评论')}</div></div>`;}
function uploadInput(key,label,multiple=false){const files=ui.uploads[key]||[];return `<div class="field full"><span>${E(label)}</span><div class="upload-box">${files.map((src,i)=>`<div><img src="${E(safeImg(src))}" alt="待保存图片">${B('remove-image','移除',key+'|'+i,'text-btn danger')}</div>`).join('')}<div class="grow"><input type="file" accept="image/png,image/jpeg,image/webp" ${multiple?'multiple':''} data-upload="${E(key)}" aria-label="${E(label)}"><p class="muted small">JPG / PNG / WebP，${multiple?'最多3张，':''}单张原图不超过8MB，自动压缩保存。</p></div></div></div>`;}
function publish(){const d=draft('publish',{content:'',tag:'晒宠',topic:'养宠日常'});return head('记录今天的小确幸。','分享有礼：每次有效发布获得10积分。')+`<div class="reading card pad">${formStart('publish','publish')}<div class="form-grid">${textarea('content','发生了什么可爱的事？',d.content,'required minlength="5" maxlength="2000" placeholder="分享你的养宠日常、农场体验或小经验…"')}${select('tag','动态分类',d.tag,['晒宠','经验分享','知识'])}${field('topic','参与话题',d.topic,'text','required maxlength="30"')}${uploadInput('publish','添加照片（可选）',true)}</div>${formEnd('发布动态')}</div>`;}
function knowledge(){const q=ui.filters.knowledgeq||'',cat=ui.filters.knowledge||'全部',list=S.articles.filter(a=>(cat==='全部'||a.category===cat)&&a.title.includes(q));return head('更懂它，才能更爱它。','有用的养宠知识，陪你一起成长。')+filters('knowledge',['全部','科学喂养','健康养护'].map(x=>[x,x]))+`<div style="margin-bottom:22px">${searchForm('knowledgeq','搜索养宠知识')}</div>`+(list.length?`<div class="grid two">${list.map(articleCard).join('')}</div>`:empty('没有找到相关文章','换个关键词试试。'));}
function article(id){const a=get(S.articles,id);if(!a)return missing();if(!S.reads.includes(id)){Farm.readArticle(id);S=Farm.get();}return head('养宠知识库')+`<article class="reading card pad">${img(a.art,a.title,'article-hero')}<div class="spacer"></div>${pill(a.category)}<h1 style="margin:16px 0">${E(a.title)}</h1><p class="muted small">农场养宠编辑部 · ${get(S.articles,id).reads.toLocaleString()} 阅读</p><div class="article-body">${a.body.map(([h,t])=>`<h2>${E(h)}</h2><p>${E(t)}</p>`).join('')}</div><div class="note" style="margin-top:25px">日常养护科普，具体健康计划请结合专业人员意见。</div><div class="post-footer">${B('like-article',I('heart')+' '+a.likes,id,a.liked?'liked':'')}${B('favorite',I('star')+(fav('article',id)?' 已收藏':' 收藏文章'),'article|'+id,fav('article',id)?'liked':'')}${B('share',I('share')+' 分享','','')}</div></article>`;}
function profile(){const l=Farm.level(S);return head('我的陪伴日记。','把属于你和毛孩子的每件小事，认真收藏。')+`<div class="profile-hero">${img('dog','我的头像','avatar avatar-lg')}<div class="grow"><h1>${E(S.user.name)}</h1><p>${E(S.user.phone)} · 让陪伴成为日常</p>${A('member','L'+l.n+' · '+l.name+' '+I('arrow'),'pill')}</div>${A('settings',I('settings'),'icon-btn')}</div><div class="stats">${[['points',S.user.points,'我的积分'],['coupons',S.coupons.filter(c=>Farm.couponState(c)==='available').length,'可用优惠券'],['orders',S.orders.length,'全部订单'],['favorites',S.favorites.length,'我的收藏']].map(([r,n,t])=>A(r,`<strong>${n}</strong><span>${t}</span>`,'stat')).join('')}</div>${section('我的订单','每次相遇都有迹可循',A('orders','全部订单 '+I('arrow'),'text-btn'))}<div class="grid four">${[['pending','clock','待支付'],['paid','ticket','待履约'],['done','check','已完成'],['closed','shield','退款 / 售后']].map(([f,i,t])=>B('profile-orders',`${I(i)}<div><h3>${t}</h3><p>${S.orders.filter(o=>f==='paid'?['paid','shipped','return_requested','in_service'].includes(o.status):f==='closed'?['cancelled','refunded'].includes(o.status):o.status===f).length} 笔订单</p></div>`,f,'menu-item')).join('')}</div>${section('我的宠物','健康成长，点滴记录',A('pets','管理档案 '+I('arrow'),'text-btn'))}<div class="grid two">${S.pets.slice(0,2).map(p=>petCard(p)).join('')||empty('添加你的第一位毛孩子','',A('pet-edit/new','新增宠物','btn'))}</div>${section('常用服务')}<div class="menu-grid">${[['member','spark','会员中心','等级、折扣与专属权益'],['points','coins','积分中心','签到、兑换与收支明细'],['coupons','ticket','优惠券','查看门槛、期限与适用范围'],['addresses','pin','收货地址','新增、编辑与默认地址'],['favorites','heart','我的收藏','活动、商品与养宠知识'],['messages','bell','消息中心','订单动态与健康提醒'],['service/boarding','house','萌宠寄养','安心寄养，按晚预订'],['service/grooming','scissors','洗护美容','选择项目、技师与时段'],['adoption','paw','爱心领养','申请、审核与领养回访'],['promo','gift','邀请有礼','邀请、拼团与助力活动'],['support','chat','在线客服','本地问答与问题记录'],['settings','settings','账号与数据','资料、备份与演示设置']].map(x=>linkCard(...x)).join('')}</div>`;}
function petCard(p){return A('health/'+p.id,`<img src="${E(p.avatar?safeImg(p.avatar):art(p.art))}" alt="${E(p.name)}"><div class="grow"><h3>${E(p.name)} ${pill(p.gender)}</h3><p>${E(p.breed)} · ${Math.floor(Farm.days(p.birthday,Farm.day())/365)}岁</p><span class="muted small">${p.weight}kg · ${p.neutered?'已绝育':'未绝育'}</span></div>${I('chevron')}`,'card pet-card');}
function pets(){return head('我家的毛孩子。','每一个小生命，都有属于自己的成长档案。',A('pet-edit/new',I('plus')+' 添加宠物','btn'))+(S.pets.length?`<div class="grid two">${S.pets.map(petCard).join('')}</div>`:empty('第一份陪伴，从这里开始','',A('pet-edit/new','添加宠物','btn')));}
function petEdit(id){const p=id==='new'?{}:get(S.pets,id);if(!p)return missing();const key='pet-edit/'+id,d=draft(key,{id:p.id||'',name:p.name||'',species:p.species||'犬',breed:p.breed||'',gender:p.gender||'公',birthday:p.birthday||Farm.day(-365),weight:p.weight||'',neutered:p.neutered||false,chip:p.chip||''});return head(p.id?'编辑宠物档案':'认识一位新朋友。','新增有效宠物档案奖励20积分，编辑不会重复奖励。')+`<div class="reading card pad">${formStart('pet',key)}${hidden('id',d.id)}<div class="form-grid">${field('name','宠物昵称',d.name,'text','required maxlength="20"')}${select('species','物种',d.species,['犬','猫','兔','其他'])}${field('breed','品种',d.breed,'text','required maxlength="30"')}${select('gender','性别',d.gender,['公','母'])}${field('birthday','出生日期',d.birthday,'date',`required max="${Farm.day()}"`)}${field('weight','当前体重（kg）',d.weight,'number','required min="0.01" max="150" step="0.01"')}${field('chip','芯片编号（选填）',d.chip,'text','maxlength="60"')}<div class="field" style="justify-content:center">${check('neutered','已绝育',d.neutered)}</div>${uploadInput(key,'宠物头像（可选）')}</div>${p.avatar?`<p class="muted small" style="margin-top:12px">已保存头像，上传新图可替换。</p>`:''}${formEnd('保存宠物档案')}</div>`;}
function weightChart(p){const list=p.weights.slice(-12),values=list.map(w=>w.value),min=Math.max(0,Math.min(...values)-1),max=Math.max(...values)+1,points=list.map((w,i)=>[35+(list.length===1?0:i/(list.length-1))*510,125-(w.value-min)/(max-min)*90]);return `<svg class="weight-chart" viewBox="0 0 580 165" role="img" aria-label="${E(p.name)}最近${list.length}次体重趋势">${[35,80,125].map(y=>`<path d="M35 ${y}H550" stroke="#e7ece5" stroke-dasharray="4 5"/>`).join('')}<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#7eaa89" stroke-width="3"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#2c674e"/><text x="${x}" y="${y-12}" text-anchor="middle" fill="#718473" font-size="11">${list[i].value}</text><text x="${x}" y="151" text-anchor="middle" fill="#9ba89b" font-size="9">${list[i].date.slice(5)}</text>`).join('')}</svg>`;}
function health(id){const p=get(S.pets,id);if(!p)return head('健康档案')+empty('先建立宠物档案','',A('pets','我的宠物','btn'));const tab=ui.filters.health||'all',records=S.health.filter(h=>h.petId===id&&(tab==='all'||h.kind===tab)).sort((a,b)=>b.date.localeCompare(a.date));return head(p.name+'的健康手册。','每一次记录，都让健康多一份安心。',A('pet-edit/'+id,I('edit')+' 编辑档案','btn outline'))+`<div class="card pad"><div class="pet-profile"><img src="${E(p.avatar?safeImg(p.avatar):art(p.art))}" alt="${E(p.name)}"><div class="grow"><h2>${E(p.name)} ${pill(p.gender)}</h2><p class="muted small">${E(p.species+' · '+p.breed)} · ${p.birthday}出生<br>${p.neutered?'已绝育':'未绝育'} · 芯片 ${E(p.chip||'未登记')}</p></div><span class="price">${p.weight}<small> kg</small></span></div><div class="between"><h3>体重成长曲线 <small class="muted">kg</small></h3>${B('weight','+ 记录体重',id,'text-btn')}</div>${weightChart(p)}</div>${section('健康记录','档案按宠物分别保存',A('health-edit/'+id+'/new',I('plus')+' 新增记录','btn small'))}${filters('health',[['all','全部记录'],['vaccine','疫苗接种'],['worm','驱虫护理'],['checkup','健康体检']])}<div class="two-col"><div class="card pad">${records.length?records.map(h=>`<div class="health-record"><div class="between"><h3>${pill(kindNames[h.kind])} ${E(h.name)}</h3>${A('health-edit/'+id+'/'+h.id,I('edit')+' 编辑','text-btn')}</div><p>${E(h.type)} · ${E(h.provider)}<br>本次 ${h.date}${h.batch?' · 批号 '+E(h.batch):''}</p>${h.next?`<div style="margin-top:10px">${pill('下次 '+h.next+' · '+(Farm.days(Farm.day(),h.next)<0?'逾期'+(-Farm.days(Farm.day(),h.next))+'天':'还有'+Farm.days(Farm.day(),h.next)+'天'),Farm.days(Farm.day(),h.next)<=7?'orange':'')}</div>`:''}${h.note?`<p class="pre">${E(h.note)}</p>`:''}${h.photo?`<img src="${E(safeImg(h.photo))}" alt="健康记录凭证" style="width:120px;border-radius:10px;margin-top:13px" data-action="view-image" data-id="${E(h.photo)}">`:''}</div>`).join(''):empty('还没有这类记录','点击新增，记录一次细心的照顾。')}</div><aside class="stack"><div class="card pad"><h3>定期体检，多一份安心</h3><p class="muted small" style="margin:14px 0 18px">体检预约与健康档案独立管理；完成服务后可登记实际检查报告。L3 / L4每季享免费体检次数。</p>${A('service/checkup','预约健康体检 '+I('arrow'),'btn full')}</div><div class="note">健康提醒根据“下次日期”自动计算，临近7天及逾期项目会出现在消息中心。</div></aside></div>`;}
function healthEdit(petId,id){const p=get(S.pets,petId),h=id==='new'?{}:get(S.health,id);if(!p||!h||h.petId&&h.petId!==petId)return missing();const key='health-edit/'+petId+'/'+id,d=draft(key,{id:h.id||'',petId,kind:h.kind||'vaccine',type:h.type||'狂犬疫苗',name:h.name||'',date:h.date||Farm.day(),next:h.next||'',provider:h.provider||'',batch:h.batch||'',note:h.note||''});return head((h.id?'编辑':'新增')+p.name+'的健康记录','实际记录不可填未来日期；新增疫苗奖励10积分。')+`<div class="reading card pad">${formStart('health',key)}${hidden('id',d.id)}${hidden('petId',petId)}<div class="form-grid">${select('kind','记录类别',d.kind,Object.entries(kindNames),h.id?'disabled':'')}${h.id?hidden('kind',h.kind):''}${field('type','项目类型',d.type,'text','required maxlength="40" list="healthtypes"')}<datalist id="healthtypes">${['狂犬疫苗','四联疫苗','犬瘟热疫苗','细小病毒疫苗','猫三联','体内驱虫','体外驱虫','年度体检'].map(x=>`<option value="${x}">`).join('')}</datalist>${field('name','疫苗 / 药品 / 检查名称',d.name,'text','required maxlength="60"')}${field('provider','接种 / 服务机构',d.provider,'text','required maxlength="60"')}${field('date','实际记录日期',d.date,'date',`required max="${Farm.day()}"`)}${field('next','下次日期（选填）',d.next,'date')}${field('batch','生产批号（选填）',d.batch,'text','maxlength="50"')}${textarea('note','备注 / 检查结果',d.note,'maxlength="500"')}${uploadInput(key,'上传凭证（可选）')}</div>${formEnd('保存健康记录')}</div>`;}
const $=s=>document.querySelector(s), E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), I=Icons, M=n=>'¥'+Farm.money(n), art=k=>'assets/images/'+(/^[a-z-]+$/.test(k||'')?k:'farm')+'.svg';
const safeImg=s=>/^assets\/images\/[a-z-]+\.svg$/.test(s||'')||/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s||'')?s:art('farm');
const img=(k,alt='',cls='')=>`<img src="${E(art(k))}" alt="${E(alt)}" class="${cls}" loading="lazy">`;
const dateTime=t=>new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const fullTime=t=>new Date(t).toLocaleString('zh-CN');
const A=(route,label,cls='')=>`<a href="#${E(route)}" data-route="${E(route)}" class="${cls}">${label}</a>`;
const B=(action,label,id='',cls='btn outline',extra='')=>`<button type="button" data-action="${action}" data-id="${E(id)}" class="${cls}" ${extra}>${label}</button>`;
const pill=(text,cls='')=>`<span class="pill ${cls}">${E(text)}</span>`;
const statNames={pending:'待支付',paid:'待使用',shipped:'待收货 / 提货',done:'已完成',cancelled:'已取消',refunded:'已退款',return_requested:'退货处理中',in_service:'寄养中'};
const kindNames={vaccine:'疫苗',worm:'驱虫',checkup:'体检'};
const status=o=>o.type==='shop'&&o.status==='paid'?'待发货 / 备货':statNames[o.status];
let S=Farm.get(), route='', current='', depth=0, toastTimer, heroTimer;
const ui={hero:0,filters:{},drafts:{},spec:{},uploads:{},cartEdit:false};
const draft=(key,defaults={})=>ui.drafts[key]||(ui.drafts[key]={...defaults});
const get=(list,id)=>list.find(x=>x.id===id);
const fav=(type,id)=>S.favorites.some(f=>f.type===type&&f.id===id);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function error(e,form){const target=form?.querySelector('.form-error');if(target){target.textContent=e.message||e;target.scrollIntoView({block:'nearest'});}else toast(e.message||e);}
function head(title,sub='',action=''){return `<div class="page-title">${route!=='home'?B('back',I('back')+' 返回','','back'):''}<div class="between"><div><div class="eyebrow">PAW FARM · 萌宠农场</div><h1>${E(title)}</h1>${sub?`<p>${E(sub)}</p>`:''}</div>${action}</div></div>`;}
const section=(title,sub='',link='')=>`<div class="section-head"><h2>${E(title)}${sub?`<small>${E(sub)}</small>`:''}</h2>${link}</div>`;
const empty=(title,desc='',link='')=>`<div class="empty">${I('paw')}<h3>${E(title)}</h3><p>${E(desc)}</p>${link}</div>`;
function field(name,label,value='',type='text',extra=''){return `<label class="field"><span>${E(label)}</span><input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;}
function select(name,label,value,options,extra=''){return `<label class="field"><span>${E(label)}</span><select name="${name}" ${extra}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(t)}</option>`;}).join('')}</select></label>`;}
function textarea(name,label,value='',extra=''){return `<label class="field full"><span>${E(label)}</span><textarea name="${name}" ${extra}>${E(value)}</textarea></label>`;}
const hidden=(n,v)=>`<input type="hidden" name="${n}" value="${E(v)}">`;
const check=(name,label,value,extra='')=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''} ${extra}>${label}</label>`;
const formEnd=(label='保存')=>`<div class="error form-error" role="alert"></div><div class="form-actions"><button class="btn" type="submit">${label}${I('arrow')}</button></div></form>`;
function formStart(type,key,cls=''){return `<form data-form="${type}" data-key="${E(key)}" class="${cls}">`;}
function contactFields(d){return field('name','联系人',d.name,'text','required maxlength="30" autocomplete="name"')+field('phone','联系电话',d.phone,'tel','required pattern="1[3-9][0-9]{9}" maxlength="11" autocomplete="tel"');}
function petSelect(d,optional=false){return select('petId','关联宠物',d.petId,[...(optional?[['','暂不携宠']]:[]),...S.pets.map(p=>[p.id,p.name+' · '+p.breed])]);}
function linkCard(route,icon,title,desc=''){return A(route,`${I(icon)}<div class="grow"><h3>${E(title)}</h3><p>${E(desc)}</p></div>${I('chevron')}`,'menu-item');}
function activityCard(a){return `<article class="card activity-card" data-route="activity/${E(a.id)}" tabindex="0" role="link" aria-label="${E(a.name)}"><div class="card-image">${img(a.art,a.name)}${pill(a.tag,'white')}</div><div class="card-body"><h3>${E(a.name)}</h3><p>${a.minutes}分钟 · ${E(a.location)}</p><div class="between"><span class="price"><small>¥</small>${Farm.money(a.price)}<small> / 成人</small></span><span class="text-btn">去体验 ${I('arrow')}</span></div></div></article>`;}
function productCard(p){return `<article class="card product-card"><a href="#product/${p.id}" data-route="product/${p.id}" class="card-image" style="display:block">${img(p.art,p.name)}${p.stock<5?pill(p.stock?'仅剩'+p.stock+'件':'暂时售罄','white'):''}</a><div class="card-body">${A('product/'+p.id,`<h3>${E(p.name)}</h3>`)}<p>${E(p.category)} · 已售 ${E(p.sales)}</p><div class="between"><span class="price"><small>¥</small>${Farm.money(p.price)}<del>¥${Farm.money(p.oldPrice)}</del></span>${B('add-cart',I('plus'),p.id,'icon-btn',`aria-label="加入${E(p.name)}" ${p.stock?'':'disabled'}`)}</div></div></article>`;}
function articleCard(a){return A('article/'+a.id,`${img(a.art,a.title)}<div class="grow"><span class="eyebrow">${E(a.category)}</span><h3>${E(a.title)}</h3><span class="muted small">${a.reads.toLocaleString()} 阅读 · ${a.likes} 赞</span></div>`,'card article-card');}
function memberCard(){const l=Farm.level(S),next=Farm.levels[l.n];return `<div class="card member-card pad"><div class="between"><span class="eyebrow">PAW CLUB</span>${I('spark')}</div><h2 style="margin-top:12px">${E(l.name)} <small>L${l.n}</small></h2><p>让每一份陪伴，都有回响。</p><div class="progress"><i style="width:${next?Math.min(100,S.user.growth/next.min*100):100}%"></i></div><div class="between small" style="color:#bacdb9"><span>${S.user.growth} 成长值</span><span>${next?'距L'+next.n+'还差'+(next.min-S.user.growth):'已达最高等级'}</span></div>${A('member','查看我的权益 '+I('arrow'),'btn small full')}<div class="between" style="margin-top:15px;font-size:11px;color:#c7d4c5"><span>${S.user.points} 积分</span><span>活动享 ${l.discount/10} 折</span></div></div>`;}
const quick=[['activities','paw','农场撸宠'],['shop','bag','宠物商城'],['knowledge','book','知识专栏'],['health/'+(S.pets[0]?.id||''),'health','健康档案'],['health/'+(S.pets[0]?.id||''),'shield','疫苗提醒'],['service/boarding','house','萌宠寄养'],['service/grooming','scissors','洗护美容'],['adoption','heart','爱心领养'],['promo','gift','邀请有礼'],['member','spark','会员中心']];
function hero(){const slides=[['本周的快乐，从这里开始','把周末，\n留给可爱。','草地、阳光和毛茸茸的小伙伴，\n一起收藏一段柔软的时光。','预约农场体验','activities','farm'],['给毛孩子，多一份偏爱','好物与爱，\n一起到家。','精选口粮与陪伴好物，新人满99减20元，\n优惠券按实际条件抵扣。','发现宠物好物','shop','food'],['每次陪伴，都值得奖励','陪伴有礼，\n快乐加倍。','每周三会员日，消费积分再翻倍。\n签到、记录与分享，积攒日常的小确幸。','查看会员权益','member','dog']];const s=slides[ui.hero];return `<div class="hero"><div class="hero-copy">${pill('✦ '+s[0],'white')}<h1 class="pre">${s[1]}</h1><p class="pre">${s[2]}</p>${A(s[4],s[3]+' '+I('arrow'),'btn')}</div>${img(s[5],'农场插画')}<div class="dots">${slides.map((_,i)=>B('hero','',i,i===ui.hero?'active':'',`aria-label="第${i+1}张横幅"`)).join('')}</div></div>`;}
function home(){const pet=S.pets[0],reminders=S.settings.notify?Farm.notifications().filter(m=>m.category==='health'):[];return `${head('你好，今天也要开心呀。','来农场，和毛孩子一起把日子过得可爱一点。')}<div class="home-grid"><div><div id="hero">${hero()}</div><div class="quick-links">${quick.map(([r,i,t])=>A(r,`<span>${I(i)}</span>${t}`,'quick-link')).join('')}</div>${section('赴一场萌宠之约','与可爱不期而遇',A('activities','全部活动 '+I('arrow'),'text-btn'))}<div class="grid three">${S.activities.map(activityCard).join('')}</div>${section('毛孩子的心头好','精挑细选，安心宠爱',A('shop','逛逛商城 '+I('arrow'),'text-btn'))}<div class="grid four home-products">${S.products.slice(0,4).map(productCard).join('')}</div>${section('做更懂它的家人','科学养宠，从这里开始',A('knowledge','更多知识 '+I('arrow'),'text-btn'))}<div class="grid two">${S.articles.slice(0,2).map(articleCard).join('')}</div></div><aside class="rail">${memberCard()}<div class="card pad"><div class="between"><h3>我的毛孩子</h3>${A('pets',I('arrow'),'text-btn')}</div>${pet?S.pets.slice(0,2).map(p=>A('health/'+p.id,`<img src="${E(p.avatar?safeImg(p.avatar):art(p.art))}" alt="${E(p.name)}"><div><h3>${E(p.name)} ${pill(p.gender)}</h3><p>${E(p.breed)} · ${p.weight}kg</p></div>`,'mini-list')).join(''):A('pet-edit/new','建立第一份宠物档案','btn secondary full')}<div class="reminder"><div class="row">${I('bell')}<strong>健康小提醒</strong></div><p style="margin:7px 0">${reminders.length?E(reminders[0].title)+' · '+E(reminders[0].body):S.settings.notify?'目前没有即将到期的记录。':'页面提醒已关闭，可在设置中重新开启。'}</p>${A('messages','查看全部提醒 →','text-btn')}</div></div><div class="card pad"><span class="eyebrow">FARM NOTES</span><h3 style="margin:10px 0">小小农场，大大快乐</h3><p class="muted small">周一至周日 09:00—18:30<br>深圳市南山区 · 萌宠农场<br>陪伴，是最好的礼物。</p>${img('farm','农场风景')}</div></aside></div>`;}
function activities(){return head('把快乐，预约好。','三种亲密体验，找到属于你的治愈时光。')+`<div class="banner"><div><h2>今日份可爱，正在营业</h2><p>提前7天预约 · 按实际成人与儿童人数计价 · 会员活动折扣自动享</p></div>${I('sun')}</div><div class="grid three">${S.activities.map(activityCard).join('')}</div>`;}
function activity(id){const a=get(S.activities,id);if(!a)return missing();return head(a.name,a.desc)+`<div class="two-col"><div class="stack">${img(a.art,a.name,'detail-art')}<div class="card pad"><h2>这场约会有什么？</h2><p class="muted" style="margin:18px 0">${E(a.detail)}</p><div class="grid two">${[['clock',a.minutes+'分钟互动体验'],['pin',a.location],['shield','专业工作人员陪同'],['paw','温柔互动 · 爱护萌宠']].map(([i,t])=>`<div class="row small">${I(i)}${E(t)}</div>`).join('')}</div></div><div class="card pad"><h3>出发前的小提醒</h3><ul class="detail-list"><li>适合3岁以上儿童与成人，成人至少1位，所有入场人数均占名额。</li><li>提供互动道具和防护用品，专业饲养员全程陪同。</li><li>提前10分钟到场，凭订单二维码核销。活动结束可领取本地演示纪念卡。</li><li>提前24小时可免费退款或改期；临近场次请联系演示客服。</li><li>不追逐、不投喂自带食物，遵从工作人员引导。</li><li>携宠仅作档案关联，不额外收费，请提前沟通物种与健康状况。</li></ul></div>${activityReviews(a)}</div><div class="card detail-copy summary"><span class="eyebrow">A LITTLE TIME, A LOT OF LOVE</span><h1>${E(a.name)}</h1>${pill(a.tag)}<p>${E(a.desc)}</p><div class="price">${M(a.price)}<small> / 成人</small></div><div class="note">儿童 ${M(a.child)} / 位 · 每场空间可容纳 ${a.capacity} 人<br>当前L${Farm.level(S).n}会员活动 ${Farm.level(S).discount/10} 折，结算自动计算。</div><div class="spacer"></div>${A('booking/'+a.id,'选择日期，预约体验 '+I('arrow'),'btn full')}<div class="row" style="margin-top:14px">${B('favorite',I('heart')+(fav('activity',id)?' 已收藏':' 收藏活动'),'activity|'+id,'btn outline grow'+(fav('activity',id)?' liked':''))}${B('share',I('share')+' 分享','','btn outline grow')}</div></div></div>`;}
function pricing(q,label='商品 / 服务金额'){return `<div class="price-list"><div><span>${label}</span><span>${M(q.subtotal)}</span></div>${q.memberDiscount?`<div><span>会员活动折扣</span><span>−${M(q.memberDiscount)}</span></div>`:''}<div><span>${q.freeCheck?'会员免费体检':'优惠券'}</span><span>${q.couponDiscount?'−':''}${M(q.couponDiscount)}</span></div><div><span>积分抵扣（${q.pointsUsed}分）</span><span>−${M(q.pointsUsed)}</span></div>${q.shipping?`<div><span>配送费</span><span>${M(q.shipping)}</span></div>`:''}<div class="total"><span>应付合计</span><strong>${M(q.total)}</strong></div></div>`;}
function offers(d,type,subtotal){const benefitQuarter=Farm.quarter(type==='checkup'&&d.date?d.date:Farm.day());const usedChecks=S.orders.filter(o=>o.freeCheck&&o.quarter===benefitQuarter&&!['cancelled','refunded'].includes(o.status)).length;const remaining=Math.max(0,Farm.level(S).checks-usedChecks);if(type==='checkup'&&!remaining)d.freeCheck=false;const base=Farm.quote({type,subtotal});const list=S.coupons.filter(c=>Farm.couponValid(c,type,subtotal-base.memberDiscount));if(d.couponId&&!list.some(c=>c.id===d.couponId))d.couponId='';return `<div class="stack">${select('couponId','使用优惠券',d.couponId||'',[['','暂不使用优惠券'],...list.map(c=>[c.id,c.name+' · 减'+M(c.amount)+' / 满'+M(c.min)])],'data-reprice')}${check('usePoints',`使用积分抵扣（余额 ${S.user.points} 分，最多抵扣优惠后金额20%）`,d.usePoints,'data-reprice')}${type==='checkup'?check('freeCheck',`使用免费体检权益（${benefitQuarter}剩余${remaining}次）`,d.freeCheck,'data-reprice'+(!remaining?' disabled':'')):''}</div>`;}
function booking(id){const a=get(S.activities,id);if(!a)return missing();const key='booking/'+id,d=draft(key,{activityId:id,date:Farm.day(1),slot:'09:00',adults:1,kids:0,petId:'',name:S.user.name,phone:S.user.phone,couponId:'',usePoints:false});const subtotal=Math.round(a.price*Math.min(30,Math.max(0,Number(d.adults)||0))+a.child*Math.min(30,Math.max(0,Number(d.kids)||0))),off=offers(d,'activity',subtotal),q=Farm.quote({type:'activity',subtotal,...d});return head('预约一段可爱时光',a.name+' · 成人'+M(a.price)+' / 儿童'+M(a.child))+formStart('booking',key)+hidden('activityId',id)+`<div class="two-col"><div class="stack"><div class="card pad"><h3>01 · 选一个好日子</h3><div class="date-grid">${Array.from({length:7},(_,i)=>{const date=Farm.day(i),dt=new Date(date+'T12:00:00');return B('booking-date',`${i===0?'今天':'周'+['日','一','二','三','四','五','六'][dt.getDay()]}<strong>${date.slice(8)}</strong>${dt.getMonth()+1}月`,date,'date-btn'+(d.date===date?' active':''));}).join('')}</div><h3>02 · 选一个喜欢的时段</h3><div class="slot-grid" style="margin-top:15px">${Farm.slots(a).map(t=>{const n=Farm.available(id,d.date,t.start),past=new Date(d.date+'T'+t.start+':00')<=new Date();return B('booking-slot',`${t.start}—${t.end}<small>${past?'已开始':n?'余位 '+n+' 人':'已约满'}</small>`,t.start,'slot'+(d.slot===t.start?' active':''),past||!n?'disabled':'');}).join('')}</div>${hidden('date',d.date)}${hidden('slot',d.slot)}</div><div class="card pad"><h3 style="margin-bottom:18px">03 · 谁和你一起去？</h3><div class="form-grid">${field('adults','成人（至少1人）',d.adults,'number','min="1" max="30" required data-reprice')}${field('kids','儿童',d.kids,'number','min="0" max="30" required data-reprice')}${petSelect(d,true)}<div></div>${contactFields(d)}</div></div></div><div class="card pad summary"><h3>预约明细</h3><p class="muted small" style="margin:12px 0 20px">${E(a.name)}<br>${E(d.date)} · ${E(d.slot||'请选择时段')}<br>${E(d.adults)}成人 / ${E(d.kids)}儿童</p>${off}${pricing(q,'体验原价')}<div class="note small">提交后名额、优惠券与抵扣积分保留15分钟。付款后获得订单专属二维码。</div><div class="error form-error" role="alert"></div><button type="submit" class="btn full" style="margin-top:18px">提交预约 · ${M(q.total)} ${I('arrow')}</button><p class="muted small" style="margin-top:10px">提前24小时可退改。付款为本地演示，不产生实际扣款。</p></div></div></form>`;}
function filters(key,options){const v=ui.filters[key]||options[0][0];return `<div class="filter-bar">${options.map(([id,t])=>B('filter',E(t),key+'|'+id,'chip'+(v===id?' active':''))).join('')}</div>`;}
function searchForm(key,placeholder){return `<form data-form="filter-search" data-key="${key}" class="search">${I('search')}<input name="q" value="${E(ui.filters[key]||'')}" placeholder="${E(placeholder)}" aria-label="${E(placeholder)}"><button aria-label="搜索">${I('arrow')}</button></form>`;}
function shop(){const cat=ui.filters.shop||'全部',q=ui.filters.shopq||'',sort=ui.filters.sort||'recommend';let list=S.products.filter(p=>(cat==='全部'||p.category===cat)&&p.name.toLowerCase().includes(q.toLowerCase()));if(sort==='asc')list.sort((a,b)=>a.price-b.price);if(sort==='desc')list.sort((a,b)=>b.price-a.price);return head('好好吃饭，好好陪伴。','为毛孩子精选的日常，每一件都带着爱。',A('cart',I('cart')+' 购物车 '+S.cart.reduce((v,c)=>v+c.qty,0),'btn secondary'))+`<div class="banner"><div><span class="eyebrow">EVERYDAY ESSENTIALS</span><h2>把宠爱，装进每一天</h2><p>新人满99减20元 · 快递满99包邮 · 到店自提免运费</p></div>${I('bag')}</div>`+filters('shop',['全部','主粮','零食','洗护','玩具','用品'].map(x=>[x,x]))+`<div class="between wrap" style="margin-bottom:22px"><span class="muted small">共 ${list.length} 件好物</span><div class="row wrap">${searchForm('shopq','搜索商品名称')}<select class="input" style="width:130px" data-filter="sort" aria-label="商品排序">${[['recommend','推荐排序'],['asc','价格从低到高'],['desc','价格从高到低']].map(([v,t])=>`<option value="${v}" ${v===sort?'selected':''}>${t}</option>`).join('')}</select></div></div>`+(list.length?`<div class="grid four">${list.map(productCard).join('')}</div>`:empty('没有找到这件好物','换个关键词或分类试试。'));}
function product(id){const p=get(S.products,id);if(!p)return missing();const spec=ui.spec[id]||p.specs[0],factor=spec==='双件装'?2:1;return head('给它的心意，刚刚好。',p.category+' · 农场好物')+`<div class="two-col"><div class="stack">${img(p.art,p.name,'detail-art')}<div class="card pad"><h3>关于这件好物</h3><p class="muted" style="margin-top:14px">${E(p.name)}。农场精选日常用品，适配实际宠物需求选购。标准装为1件，双件装为2件同款商品，库存按单件计算。</p><div class="spacer"></div><div class="row small">${I('shield')}农场精选 ${I('truck')}满99包邮 ${I('house')}支持到店自提</div></div></div><div class="card detail-copy summary"><span class="eyebrow">FOR YOUR LITTLE FRIEND</span><h1>${E(p.name)}</h1>${pill(p.category)}<div class="price">${M(p.price*factor)} <del class="muted small">${M(p.oldPrice*factor)}</del></div><p>已售 ${E(p.sales)} · 当前可售库存 ${p.stock} 件</p><h3>选择规格</h3><div class="specs">${p.specs.map(s=>B('spec',E(s),id+'|'+s,'spec'+(s===spec?' active':''))).join('')}</div><div class="row wrap">${B('add-cart',I('plus')+' 加入购物车',id,'btn secondary grow',p.stock<factor?'disabled':'')}${B('buy', '立即购买 '+I('arrow'),id,'btn grow',p.stock<factor?'disabled':'')}</div><div class="row" style="margin-top:14px">${B('favorite',I('heart')+(fav('product',id)?' 已收藏':' 收藏商品'),'product|'+id,'btn outline grow'+(fav('product',id)?' liked':''))}${B('share',I('share')+' 分享','','btn outline grow')}</div></div></div>${section('宠友们这样说',p.reviews.length+'条评价')}<div class="card pad">${p.reviews.slice(0,12).map(r=>`<div class="comment"><div class="between"><strong>${E(r.user)}</strong><span class="accent">${'★'.repeat(r.rating)}</span></div><p class="muted">${E(r.content)}</p></div>`).join('')}</div>`;}
function cart(){const selected=S.cart.filter(c=>c.checked),sum=selected.reduce((v,c)=>v+get(S.products,c.productId).price*c.qty*(c.spec==='双件装'?2:1),0);return head('装满喜欢，也装满爱。','选中的好物将在结算时核验库存。',S.cart.length?B('cart-edit',ui.cartEdit?'完成管理':'管理商品','','btn outline'):'')+(!S.cart.length?empty('购物车还是空的','逛逛商城，给毛孩子挑一份惊喜。',A('shop','去逛逛 '+I('arrow'),'btn')):`<div class="card">${S.cart.map(c=>{const p=get(S.products,c.productId);return `<div class="cart-line">${B('cart-toggle',I(c.checked?'check':'plus'),c.id,'icon-btn'+(c.checked?' green':''),`aria-label="${c.checked?'取消选择':'选择'}${E(p.name)}" aria-pressed="${c.checked}"`)}${img(p.art,p.name)}<div class="grow">${A('product/'+p.id,`<h3>${E(p.name)}</h3>`)}<p class="muted">${E(c.spec)} · 可售${p.stock}件</p></div><span class="price line-price">${M(p.price*(c.spec==='双件装'?2:1)*c.qty)}</span><div class="qty">${B('cart-qty','−',c.id+'|'+(c.qty-1),'',`aria-label="减少${E(p.name)}数量"`)}<strong>${c.qty}</strong>${B('cart-qty','+',c.id+'|'+(c.qty+1),'',`aria-label="增加${E(p.name)}数量"`)}</div>${ui.cartEdit?B('delete-cart',I('trash'),c.id,'icon-btn danger','aria-label="删除商品"'):''}</div>`;}).join('')}</div><div class="cart-total">${B('cart-all',I(S.cart.every(c=>c.checked)?'check':'plus')+' 全选','','text-btn')}${ui.cartEdit?B('delete-selected','删除选中','','text-btn danger'):''}<span class="muted grow">已选 ${selected.reduce((v,c)=>v+c.qty,0)} 件</span><span>合计 <strong class="price">${M(sum)}</strong></span>${B('checkout','去结算 '+I('arrow'),'cart','btn',selected.length?'':'disabled')}</div>`);}
function checkout(mode){const key='checkout/'+mode,d=draft(key,{delivery:'express',addressId:S.addresses.find(a=>a.isDefault)?.id||'',name:S.user.name,phone:S.user.phone,couponId:'',usePoints:false,note:'',qty:1,spec:'标准装'});const lines=d.buyNow?[{productId:d.productId,spec:d.spec,qty:Math.min(99,Math.max(0,Number(d.qty)||0))}]:S.cart.filter(c=>c.checked);if(!lines.length||lines.some(c=>!get(S.products,c.productId)))return head('确认订单')+empty('请先选择商品','立即购买只结算当前商品，购物车会完整保留。',A('cart','返回购物车','btn'));const subtotal=Math.max(0,Math.round(lines.reduce((v,c)=>v+get(S.products,c.productId).price*(Number(c.qty)||0)*(c.spec==='双件装'?2:1),0))),off=offers(d,'shop',subtotal),q=Farm.quote({...d,type:'shop',subtotal});return head('确认这份心意。','价格与优惠实时计算，支持快递配送或到店自提。')+formStart('checkout',key)+`<div class="two-col"><div class="stack"><div class="card pad"><h3>配送方式</h3><div class="spacer"></div>${select('delivery','选择配送方式',d.delivery,[['express','快递配送（满99免运费）'],['pickup','到店自提（免运费）']],'data-reprice')}<div class="spacer"></div>${d.delivery==='express'?`${select('addressId','收货地址',d.addressId,[['','请选择地址'],...S.addresses.map(a=>[a.id,a.name+' '+a.phone+' · '+a.area+' '+a.detail])])}<div style="margin-top:12px">${A('addresses','管理 / 新增收货地址 '+I('arrow'),'text-btn')}</div>`:`<div class="note">${I('pin')} 萌宠农场 · 南山店<br>深圳市南山区科技园路 · 09:00—18:30</div><div class="spacer"></div><div class="form-grid">${contactFields(d)}</div>`}</div><div class="card pad"><h3>你的心意清单</h3>${lines.map(c=>{const p=get(S.products,c.productId);return `<div class="mini-list">${img(p.art,p.name)}<div class="grow"><h3>${E(p.name)}</h3><p>${E(c.spec)} × ${c.qty}</p></div><strong>${M(p.price*c.qty*(c.spec==='双件装'?2:1))}</strong></div>`;}).join('')}${d.buyNow?field('qty','购买数量',d.qty,'number','min="1" max="99" required data-reprice'):''}<div class="spacer"></div>${textarea('note','订单备注（选填）',d.note,'maxlength="300" placeholder="有什么需要特别留意的？"')}</div></div><div class="card pad summary"><h3>支付明细</h3><div class="spacer"></div>${off}${pricing(q)}<div class="error form-error" role="alert"></div><button class="btn full" type="submit">创建订单 · ${M(q.total)} ${I('arrow')}</button><p class="muted small" style="margin-top:12px">订单库存预占15分钟。使用本地演示收银台，不连接真实支付。</p></div></div></form>`;}

boot();
})();
